import csv
import io
import math

import numpy as np


def _parse_csv(text, name):
    """Parse CSV text into (header, rows), skipping completely blank lines."""
    if not isinstance(text, str):
        raise ValueError(f"{name} must be a string")
    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"{name} is empty (no header row)")
    header = [h.strip() for h in header]
    if len(set(header)) != len(header):
        raise ValueError(f"{name} has duplicate column names")
    rows = []
    for line_no, row in enumerate(reader, start=2):
        if not row or all(cell.strip() == "" for cell in row) and len(row) <= 1:
            continue  # blank line
        if len(row) != len(header):
            raise ValueError(
                f"{name} line {line_no}: expected {len(header)} fields, got {len(row)}"
            )
        rows.append(row)
    return header, rows


def _to_float(cell, name, line_no, col):
    s = cell.strip()
    if s == "":
        raise ValueError(f"{name} row {line_no}, column '{col}': missing value")
    try:
        v = float(s)
    except ValueError:
        raise ValueError(
            f"{name} row {line_no}, column '{col}': non-numeric value {cell!r}"
        )
    if not math.isfinite(v):
        raise ValueError(
            f"{name} row {line_no}, column '{col}': non-finite value {cell!r}"
        )
    return v


def predict_linear_regression(train_csv, test_csv, target):
    train_header, train_rows = _parse_csv(train_csv, "train_csv")
    test_header, test_rows = _parse_csv(test_csv, "test_csv")

    if target not in train_header:
        raise ValueError(f"target column '{target}' not found in train_csv")
    if set(train_header) != set(test_header):
        raise ValueError("train_csv and test_csv must have the same columns")
    if not train_rows:
        raise ValueError("train_csv has no data rows")

    features = [c for c in train_header if c != target]
    train_idx = {c: i for i, c in enumerate(train_header)}
    test_idx = {c: i for i, c in enumerate(test_header)}

    # Build training matrices (validating every value used).
    X = np.array(
        [[_to_float(r[train_idx[c]], "train_csv", i + 1, c) for c in features]
         for i, r in enumerate(train_rows)],
        dtype=float,
    ).reshape(len(train_rows), len(features))
    y = np.array(
        [_to_float(r[train_idx[target]], "train_csv", i + 1, target)
         for i, r in enumerate(train_rows)],
        dtype=float,
    )

    # Test features only; the test target column is ignored entirely.
    X_test = np.array(
        [[_to_float(r[test_idx[c]], "test_csv", i + 1, c) for c in features]
         for i, r in enumerate(test_rows)],
        dtype=float,
    ).reshape(len(test_rows), len(features))

    # Fit OLS with intercept by centering (numerically stabler than an
    # explicit column of ones). lstsq gives the minimum-norm solution
    # if the design is rank-deficient.
    x_mean = X.mean(axis=0) if features else np.zeros(0)
    y_mean = y.mean()
    if features:
        coef, *_ = np.linalg.lstsq(X - x_mean, y - y_mean, rcond=None)
    else:
        coef = np.zeros(0)
    intercept = y_mean - x_mean @ coef

    preds = intercept + (X_test - x_mean) @ coef + x_mean @ coef \
        if False else y_mean + (X_test - x_mean) @ coef
    return [float(p) for p in preds]
```

Notes:
- Columns are matched by name, so the test CSV may list them in a different order.
- Empty cells, non-numeric text, and `nan`/`inf` in any training column or in any test feature column raise `ValueError`; the test target column is never read.
- Fitting is done on centered data with `numpy.linalg.lstsq`, so collinear features still produce a (minimum-norm) least-squares fit rather than crashing.

Example:
```python
>>> predict_linear_regression('x,y\n1,3\n2,5\n3,7\n4,9\n', 'x,y\n5,0\n10,0\n', 'y')
[11.0, 21.0]
```

