import csv
import io


def normalize_csv_columns(csv_text):
    """
    Min-max normalize every column of a numeric CSV (with a header row).

    Returns a dict mapping column name -> list of normalized floats in [0, 1],
    in row order. Columns whose values are all identical become all zeros.
    """
    reader = csv.reader(io.StringIO(csv_text))

    # Skip leading blank lines to find the header.
    header = None
    for row in reader:
        if any(cell.strip() for cell in row):
            header = [name.strip() for name in row]
            break
    if header is None:
        return {}

    if len(set(header)) != len(header):
        raise ValueError("Duplicate column names in header: %r" % header)

    columns = [[] for _ in header]
    for line_no, row in enumerate(reader, start=2):
        if not any(cell.strip() for cell in row):
            continue  # ignore blank lines (e.g. a trailing newline)
        if len(row) != len(header):
            raise ValueError(
                "Row %d has %d fields, expected %d" % (line_no, len(row), len(header))
            )
        for i, cell in enumerate(row):
            try:
                columns[i].append(float(cell))
            except ValueError:
                raise ValueError(
                    "Non-numeric value %r in column %r (row %d)"
                    % (cell, header[i], line_no)
                ) from None

    result = {}
    for name, values in zip(header, columns):
        if not values:
            result[name] = []
            continue
        lo, hi = min(values), max(values)
        span = hi - lo
        if span == 0:
            result[name] = [0.0] * len(values)
        else:
            result[name] = [(v - lo) / span for v in values]
    return result
```

Example:

