from html.parser import HTMLParser


class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)  # decodes entities in text
        self.rows = []
        self.started = False      # inside the target table
        self.finished = False     # target table fully processed
        self.depth = 0            # table nesting depth relative to the target
        self.current_row = None   # list of cell strings for the open <tr>
        self.cell_buf = None      # text pieces of the open <td>
        self.in_th = False        # inside a <th> at depth 1 (text ignored)

    # helpers
    def _close_cell(self):
        if self.cell_buf is not None and self.current_row is not None:
            self.current_row.append("".join(self.cell_buf))
        self.cell_buf = None
        self.in_th = False

    def _close_row(self):
        self._close_cell()
        if self.current_row is not None:
            self.rows.append(self.current_row)
        self.current_row = None

    # parser callbacks
    def handle_starttag(self, tag, attrs):
        if self.finished:
            return
        if not self.started:
            if tag == "table":
                cls = None
                for name, value in attrs:
                    if name == "class":
                        cls = value
                        break  # first occurrence wins, like browsers
                if cls == "data-table":
                    self.started = True
                    self.depth = 1
            return

        if tag == "table":
            self.depth += 1
            return
        if self.depth != 1:
            return  # structure of nested tables is ignored

        if tag == "tr":
            self._close_row()          # implicit close of previous row
            self.current_row = []
        elif tag == "td":
            self._close_cell()         # implicit close of previous cell
            if self.current_row is not None:
                self.cell_buf = []
        elif tag == "th":
            self._close_cell()
            if self.current_row is not None:
                self.in_th = True
        elif tag in ("thead", "tbody", "tfoot"):
            self._close_row()

    def handle_startendtag(self, tag, attrs):
        # Self-closing tags (e.g. <br/>) carry no text; don't let
        # a bogus <table/> or <tr/> alter the structure.
        if tag in ("table", "tr", "td", "th", "thead", "tbody", "tfoot"):
            return

    def handle_endtag(self, tag):
        if self.finished or not self.started:
            return

        if tag == "table":
            self.depth -= 1
            if self.depth == 0:
                self._close_row()
                self.started = False
                self.finished = True
            return
        if self.depth != 1:
            return

        if tag == "td":
            if self.cell_buf is not None:
                self._close_cell()
        elif tag == "th":
            self.in_th = False
        elif tag == "tr":
            self._close_row()
        elif tag in ("thead", "tbody", "tfoot"):
            self._close_row()

    def handle_data(self, data):
        if self.started and not self.finished and self.cell_buf is not None:
            self.cell_buf.append(data)


def extract_data_table_rows(html):
    """Return the rows (lists of <td> texts) of the first
    <table class="data-table"> in `html`, or [] if none."""
    if not html:
        return []
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    # Handle a target table left unclosed at end of input.
    if parser.started and not parser.finished:
        parser._close_row()
    return parser.rows
```

**How it works**

- Uses Python's built-in `html.parser`. With `convert_charrefs=True`, entities such as `&amp;` and `&#169;` are decoded in the text.
- It finds the first `<table>` whose `class` attribute is exactly `"data-table"`. A value like `"data-table striped"` does not match.
- It tracks how deeply tables are nested inside that one. Only `<tr>`/`<td>` tags that belong directly to the target table (depth 1) count as rows and cells. Text inside a nested table, or inside any other tags within a cell, is still kept as part of the enclosing cell's text, with the tags removed.
- Whitespace in cell text is kept exactly as written.
- `<th>` cells are skipped, since only `<td>` contents are requested. A row made only of `<th>`, or with no cells at all, gives `[]`.
- Missing closing tags are handled. A new `<td>` or `<th>` closes the open cell, and a new `<tr>`, `</tr>`, a section tag, or `</table>` closes the open row. A table left unclosed at the end of the input is also handled.

**Example**

```python
>>> extract_data_table_rows("<table class='data-table'><tr><td>Header 1</td><td>Header 2</td></tr><tr><td>Data 1</td><td>Data 2</td></tr></table>")
[['Header 1', 'Header 2'], ['Data 1', 'Data 2']]
>>> extract_data_table_rows("<table class='data-table'><tr><td> A &amp; <b>B</b> </td></tr><tr></tr></table>")
[[' A & B '], []]
>>> extract_data_table_rows("<table class='other'><tr><td>x</td></tr></table>")
[]
```

