from html.parser import HTMLParser


class _DataTableParser(HTMLParser):
    """Collects the <td> text of each row of the first <table class="data-table">."""

    def __init__(self):
        super().__init__(convert_charrefs=True)  # entities are decoded automatically
        self.rows = []
        self.depth = 0       # table nesting depth inside the target table (0 = not inside)
        self.done = False    # True once the first matching table has been closed
        self.row = None      # cells of the current row
        self.cell = None     # text pieces of the current <td>

    # Helpers
    def _close_cell(self):
        if self.cell is not None:
            self.row.append("".join(self.cell))
            self.cell = None

    def _close_row(self):
        self._close_cell()
        if self.row is not None:
            self.rows.append(self.row)
            self.row = None

    def _start_row(self):
        self._close_row()
        self.row = []

    # Parser callbacks
    def handle_starttag(self, tag, attrs):
        if self.done:
            return

        if self.depth == 0:
            if tag == "table":
                cls = None
                for name, value in attrs:
                    if name == "class":
                        cls = value
                        break  # the first class attribute wins
                if cls == "data-table":
                    self.depth = 1
            return

        if tag == "table":
            # A nested table. Its rows are not rows of the target table,
            # but its text still counts as text of the enclosing cell.
            self.depth += 1
            return
        if self.depth > 1:
            return

        if tag == "tr":
            self._start_row()
        elif tag in ("td", "th"):
            self._close_cell()
            if self.row is None:
                self.row = []  # a cell outside any <tr> implies a row
            # Only <td> cells are collected; text of a <th> is ignored.
            self.cell = [] if tag == "td" else None
        elif tag in ("thead", "tbody", "tfoot"):
            self._close_row()

    def handle_endtag(self, tag):
        if self.done or self.depth == 0:
            return

        if tag == "table":
            if self.depth > 1:
                self.depth -= 1
            else:
                self._close_row()
                self.depth = 0
                self.done = True
            return
        if self.depth > 1:
            return

        if tag in ("td", "th"):
            self._close_cell()
        elif tag in ("tr", "thead", "tbody", "tfoot"):
            self._close_row()

    def handle_data(self, data):
        if not self.done and self.cell is not None:
            self.cell.append(data)

    def finish(self):
        # The input may end before the table is closed.
        if not self.done and self.depth > 0:
            self._close_row()
            self.done = True


def extract_data_table_rows(html):
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()  # flushes any buffered text
    parser.finish()
    return parser.rows
```

