from html.parser import HTMLParser


def extract_data_table_rows(html):
    """
    Return the rows of the first <table> whose class attribute is exactly
    "data-table". Each row is a list of the text contents of its <td> cells.
    """

    class _Parser(HTMLParser):
        def __init__(self):
            # convert_charrefs=True decodes entities such as &amp; and &#169;
            super().__init__(convert_charrefs=True)
            self.rows = []
            self.depth = 0          # table nesting depth inside the target (0 = outside)
            self.done = False       # True once the target table has been closed
            self.cur_row = None     # list of finished cell strings for the current row
            self.cur_cell = None    # list of text fragments for the open <td>

        # helpers
        def _close_cell(self):
            if self.cur_cell is not None:
                self.cur_row.append("".join(self.cur_cell))
                self.cur_cell = None

        def _close_row(self):
            self._close_cell()
            self.cur_row = None

        def _start_row(self):
            self._close_row()
            self.cur_row = []
            self.rows.append(self.cur_row)

        # parser callbacks
        def handle_starttag(self, tag, attrs):
            if self.done:
                return
            if tag == "table":
                if self.depth == 0:
                    cls = None
                    for name, value in attrs:
                        if name == "class":
                            cls = value  # the first class attribute wins
                            break
                    if cls == "data-table":
                        self.depth = 1
                else:
                    self.depth += 1  # nested table inside the target
                return

            if self.depth != 1:
                return  # outside the target, or inside a nested table

            if tag == "tr":
                self._start_row()
            elif tag == "td":
                self._close_cell()
                if self.cur_row is None:  # <td> without <tr>: implicit row
                    self._start_row()
                self.cur_cell = []
            elif tag == "th":
                self._close_cell()  # a header cell implicitly ends an open td
            elif tag in ("thead", "tbody", "tfoot"):
                self._close_row()

        def handle_endtag(self, tag):
            if self.done or self.depth == 0:
                return
            if tag == "table":
                if self.depth == 1:
                    self._close_row()
                    self.depth = 0
                    self.done = True
                else:
                    self.depth -= 1
                return

            if self.depth != 1:
                return

            if tag == "td":
                self._close_cell()
            elif tag == "tr":
                self._close_row()
            elif tag in ("thead", "tbody", "tfoot"):
                self._close_row()

        def handle_data(self, data):
            # Text anywhere inside an open target cell (including inside nested
            # tags or nested tables) belongs to that cell's text content.
            if self.cur_cell is not None:
                self.cur_cell.append(data)

    parser = _Parser()
    parser.feed(html)
    parser.close()
    parser._close_row()  # finalize if the document ended without </table>
    return parser.rows
```

**How it works**

- It uses the standard library's `HTMLParser`. With `convert_charrefs=True`, entities like `&amp;` or `&lt;` are decoded before the text reaches `handle_data`.
- The target is the first `<table>` whose `class` value equals `"data-table"` exactly. A table with classes like `"data-table striped"` does not match.
- After the target table closes, the rest of the document is ignored.
- Nested tables are tracked with a depth counter. Only `<tr>` and `<td>` tags directly in the target table create rows and cells. Text inside a nested table still counts toward the enclosing cell's text, because it is part of that cell's content.
- Tags inside a cell are dropped and only their text is kept. Whitespace is preserved exactly.
- Missing end tags (e.g. `<tr><td>a<td>b<tr>...`) are handled the way browsers do: a new `<td>`, `<th>`, `<tr>`, section tag, or the end of the table closes the open cell or row.
- A `<tr>` with no `<td>` yields `[]`. If no matching table exists, or it has no rows, the result is `[]`.

