Here's an implementation that uses only the standard library. It builds a small element tree with `html.parser`, then queries it.

```python
from html.parser import HTMLParser

_VOID_TAGS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
    'meta', 'param', 'source', 'track', 'wbr',
}


class _Node:
    __slots__ = ('tag', 'attrs', 'children', 'parent')

    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []          # mix of _Node and str
        self.parent = parent

    def has_class(self, name):
        return name in (self.attrs.get('class') or '').split()

    def iter_descendants(self):
        """Yield descendant element nodes in document (pre-)order."""
        stack = [c for c in reversed(self.children) if isinstance(c, _Node)]
        while stack:
            node = stack.pop()
            yield node
            stack.extend(c for c in reversed(node.children) if isinstance(c, _Node))

    def text(self):
        parts = []
        stack = [self]
        while stack:
            item = stack.pop()
            if isinstance(item, str):
                parts.append(item)
            else:
                stack.extend(reversed(item.children))
        return ''.join(parts)


class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)   # decodes entities in text
        self.root = _Node('#root')
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        attr_dict = {}
        for k, v in attrs:
            attr_dict.setdefault(k, v if v is not None else '')
        node = _Node(tag, attr_dict, self.stack[-1])
        self.stack[-1].children.append(node)
        if tag not in _VOID_TAGS:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag not in _VOID_TAGS and self.stack[-1].tag == tag:
            self.stack.pop()

    def handle_endtag(self, tag):
        # Close the nearest matching open element; ignore stray end tags.
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def extract_article_info(html):
    builder = _TreeBuilder()
    builder.feed(html)
    builder.close()

    def first_text(container, predicate, default):
        for node in container.iter_descendants():
            if predicate(node):
                return node.text().strip()
        return default

    results = []
    for node in builder.root.iter_descendants():
        if node.tag == 'div' and node.has_class('container'):
            title = first_text(node, lambda n: n.tag == 'h1', 'No Title')
            date = first_text(node, lambda n: n.tag == 'span' and n.has_class('date'), 'No Date')
            author = first_text(node, lambda n: n.tag == 'span' and n.has_class('author'), 'No Author')
            results.append((title, date, author))
    return results
```

