How it works:
- **Class matching:** The `class` attribute is split on whitespace, so `class="post container"` matches but `class="containers"` doesn't.
- **Document order:** Container divs are visited in pre-order, so outer containers come before nested ones. Each container's search covers all of its descendants, including any nested containers.
- **Text extraction:** All descendant text is concatenated, so nested tags are dropped. `convert_charrefs=True` decodes entities like `&amp;` and `&#39;`. The result is stripped of surrounding whitespace.
- **Malformed HTML:**
  - Void tags like `<br>` and `<img>` don't break nesting.
  - An end tag closes the nearest matching open element.
  - Stray end tags are ignored.
  - Unclosed elements are closed when the input ends.

```python
from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input", "link",
    "meta", "param", "source", "track", "wbr",
}


class _ArticleParser(HTMLParser):
    def __init__(self):
        # convert_charrefs=True (the default) decodes entities in text data
        super().__init__(convert_charrefs=True)
        self.records = []          # one dict per container div, in document order
        self.open_containers = []  # indices of currently open container divs
        self.stack = []            # open elements: dicts with tag/container/captures
        self.active = []           # captures currently collecting text

    @staticmethod
    def _classes(attrs):
        for name, value in attrs:
            if name == "class" and value:
                return set(value.split())
        return set()

    def handle_starttag(self, tag, attrs):
        if tag in _VOID_TAGS:
            return
        classes = self._classes(attrs)
        entry = {"tag": tag, "container": None, "captures": []}

        # Which fields does this element supply?
        fields = []
        if tag == "h1":
            fields.append("title")
        elif tag == "span":
            if "date" in classes:
                fields.append("date")
            if "author" in classes:
                fields.append("author")

        # Start a capture for every open container that hasn't claimed the field yet.
        for idx in self.open_containers:
            rec = self.records[idx]
            for field in fields:
                if field not in rec["claimed"]:
                    rec["claimed"].add(field)
                    cap = {"record": idx, "field": field, "parts": []}
                    entry["captures"].append(cap)
                    self.active.append(cap)

        # A new container div starts a new record.
        if tag == "div" and "container" in classes:
            self.records.append({"title": None, "date": None, "author": None,
                                 "claimed": set()})
            idx = len(self.records) - 1
            entry["container"] = idx
            self.open_containers.append(idx)

        self.stack.append(entry)

    def handle_startendtag(self, tag, attrs):
        if tag in _VOID_TAGS:
            return
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_data(self, data):
        for cap in self.active:
            cap["parts"].append(data)

    def _close_entry(self, entry):
        for cap in entry["captures"]:
            self.records[cap["record"]][cap["field"]] = "".join(cap["parts"]).strip()
            self.active.remove(cap)
        if entry["container"] is not None:
            self.open_containers.remove(entry["container"])

    def handle_endtag(self, tag):
        # Ignore stray end tags; otherwise close everything up to the match
        # (implicitly closing any unclosed inner elements).
        if not any(e["tag"] == tag for e in self.stack):
            return
        while self.stack:
            entry = self.stack.pop()
            self._close_entry(entry)
            if entry["tag"] == tag:
                break

    def close(self):
        super().close()
        # Finalize anything left unclosed at end of document.
        while self.stack:
            self._close_entry(self.stack.pop())


def extract_article_info(html):
    parser = _ArticleParser()
    parser.feed(html)
    parser.close()
    return [
        (
            rec["title"] if rec["title"] is not None else "No Title",
            rec["date"] if rec["date"] is not None else "No Date",
            rec["author"] if rec["author"] is not None else "No Author",
        )
        for rec in parser.records
    ]
```

