## Notes

- **Multiple classes:** classes are split on whitespace, so `class="post container"` matches.
- **Nested containers:** an element counts for every container it is inside, as long as that container hasn't found its first one yet.
- **Malformed HTML:** unclosed elements are finalized when parsing ends, and stray `</div>` tags are ignored.
- **Empty elements:** an empty `<h1></h1>` gives the title `''`, because the element exists. The `'No Title'` default is used only when there is no `<h1>` at all.

```python
from html.parser import HTMLParser

_VOID_ELEMENTS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input", "link",
    "meta", "param", "source", "track", "wbr", "keygen", "command",
}


class _ArticleParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)  # decodes entities in text
        self.results = []          # container records, in document order
        self.active = []           # currently open container records
        self.captures = []         # currently open text captures
        self.stack = []            # open elements: dicts with tag/container/captures

    @staticmethod
    def _classes(attrs):
        for name, value in attrs:
            if name == "class" and value:
                return value.split()
        return []

    def _start_capture(self, node, field):
        for rec in self.active:
            if rec[field] is None and field not in rec["pending"]:
                rec["pending"].add(field)
                cap = {"rec": rec, "field": field, "buf": []}
                node["captures"].append(cap)
                self.captures.append(cap)

    def _finish_capture(self, cap):
        rec, field = cap["rec"], cap["field"]
        rec[field] = "".join(cap["buf"]).strip()
        rec["pending"].discard(field)
        if cap in self.captures:
            self.captures.remove(cap)

    def _pop_node(self):
        node = self.stack.pop()
        for cap in node["captures"]:
            self._finish_capture(cap)
        if node["container"] is not None and node["container"] in self.active:
            self.active.remove(node["container"])

    def handle_starttag(self, tag, attrs):
        if tag in _VOID_ELEMENTS:
            return
        node = {"tag": tag, "container": None, "captures": []}
        self.stack.append(node)
        classes = self._classes(attrs)

        if tag == "h1":
            self._start_capture(node, "title")
        elif tag == "span":
            if "date" in classes:
                self._start_capture(node, "date")
            if "author" in classes:
                self._start_capture(node, "author")

        # Register the container after handling captures, so a container's
        # own tag can never count as one of its children.
        if tag == "div" and "container" in classes:
            rec = {"title": None, "date": None, "author": None, "pending": set()}
            self.results.append(rec)
            self.active.append(rec)
            node["container"] = rec

    def handle_startendtag(self, tag, attrs):
        # Treat <x/> as an element that opens and closes immediately.
        self.handle_starttag(tag, attrs)
        if tag not in _VOID_ELEMENTS:
            self.handle_endtag(tag)

    def handle_endtag(self, tag):
        # Ignore stray end tags; otherwise close everything up to the match
        # (this tolerates unclosed inner elements).
        if not any(node["tag"] == tag for node in self.stack):
            return
        while self.stack:
            top_tag = self.stack[-1]["tag"]
            self._pop_node()
            if top_tag == tag:
                break

    def handle_data(self, data):
        for cap in self.captures:
            cap["buf"].append(data)

    def close(self):
        super().close()
        while self.stack:          # finalize anything left unclosed
            self._pop_node()


def extract_article_info(html):
    parser = _ArticleParser()
    parser.feed(html)
    parser.close()
    out = []
    for rec in parser.results:
        out.append((
            rec["title"] if rec["title"] is not None else "No Title",
            rec["date"] if rec["date"] is not None else "No Date",
            rec["author"] if rec["author"] is not None else "No Author",
        ))
    return out
