        if fields:
            capture = {"parts": []}
            used = False
            # Reserve the slot when the start tag is seen, so "first" means
            # first in document order. The text is filled in later.
            for rec in self._open_containers():
                for field in fields:
                    if rec[field] is None:
                        rec[field] = capture
                        used = True
            if used:
                self.active.append(capture)
                entry["captures"].append(capture)

        if tag == "div" and "container" in classes:
            rec = {"title": None, "date": None, "author": None}
            self.results.append(rec)
            entry["container"] = rec

        if tag in ("script", "style"):
            self.skip_depth += 1

        self.stack.append(entry)

    def handle_endtag(self, tag):
        # Find the most recent matching open tag. Ignore stray end tags.
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i]["tag"] == tag:
                break
        else:
            return
        # Pop it and anything left unclosed inside it.
        while len(self.stack) > i:
            self._pop()

    def _pop(self):
        entry = self.stack.pop()
        if entry["tag"] in ("script", "style"):
            self.skip_depth -= 1
        for capture in entry["captures"]:
            if capture in self.active:
                self.active.remove(capture)

    def handle_data(self, data):
        if self.skip_depth > 0:
            return
        for capture in self.active:
            capture["parts"].append(data)

    def finish(self):
        self.close()  # flush any buffered text
        while self.stack:
            self._pop()


def extract_article_info(html):
    parser = _ArticleParser()
    parser.feed(html)
    parser.finish()

    output = []
    for rec in parser.results:
        values = []
        for field in ("title", "date", "author"):
            capture = rec[field]
            if capture is None:
                values.append(_DEFAULTS[field])
            else:
                values.append("".join(capture["parts"]).strip())
        output.append(tuple(values))
    return output
```

This uses only the standard library's `html.parser`.

**How it works**

- **Containers:** A `<div>` counts as a container if `"container"` is one of the words in its `class` attribute, so `class="post container wide"` matches.
- **Order:** A record is created when each container's start tag is seen, so results come out in document order. Nested containers each get their own tuple.
- **Choosing the first element:** For each open container, the first matching `<h1>` or `<span class="date">`/`<span class="author">` reserves the field when its start tag appears. Text is then collected until that element closes. Text inside nested tags is included and the tags themselves are dropped. An element inside a nested container also counts for the outer container, since it is inside both.
- **Entities:** `convert_charrefs=True` decodes entities such as `&amp;` and `&#233;`. The collected text is stripped of surrounding whitespace.
- **Messy HTML:**
  - Unclosed tags are closed when an enclosing tag ends, or at the end of the input.
  - Stray end tags are ignored.
  - Void tags like `<br>` never go on the stack.
  - Text inside `<script>` and `<style>` is skipped.
- **Missing elements** produce `'No Title'`, `'No Date'` or `'No Author'`.

**Example**

```python
>>> extract_article_info('<div class="container"><h1>Hello</h1><span class="author">Ann</span></div>')
[('Hello', 'No Date', 'Ann')]
>>> extract_article_info('<div class="a container"><h1> Tom &amp; <b>Jerry</b> </h1>'
...                      '<span class="date">2024-01-01</span></div><div class="container"></div>')
[('Tom & Jerry', '2024-01-01', 'No Author'), ('No Title', 'No Date', 'No Author')]
```

