import json
import math


def key_mean_median(json_text):
    """
    Parse a JSON list of objects and compute, for each key seen in any record,
    the mean and median of that key's numeric values.

    Missing values, nulls, booleans and non-numeric values are ignored.
    Keys with no numeric values get {'mean': None, 'median': None}.
    """
    records = json.loads(json_text)
    if not isinstance(records, list):
        raise ValueError("JSON input must be a list of objects")

    values_by_key = {}  # insertion order = order of first appearance

    for record in records:
        if not isinstance(record, dict):
            continue  # skip anything that isn't a record/object
        for key, value in record.items():
            bucket = values_by_key.setdefault(key, [])
            if _is_number(value):
                bucket.append(float(value))

    result = {}
    for key, nums in values_by_key.items():
        if nums:
            result[key] = {'mean': _mean(nums), 'median': _median(nums)}
        else:
            result[key] = {'mean': None, 'median': None}
    return result


def _is_number(value):
    # bool is a subclass of int in Python, but true/false aren't numeric data.
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)):
        # Python's json accepts NaN/Infinity, so exclude non-finite values.
        return math.isfinite(value)
    return False


def _mean(nums):
    return math.fsum(nums) / len(nums)


def _median(nums):
    s = sorted(nums)
    n = len(s)
    mid = n // 2
    if n % 2:
        return float(s[mid])
    return (s[mid - 1] + s[mid]) / 2.0


if __name__ == "__main__":
