            if _is_number(value):
                bucket.append(value)

    result = {}
    for key, values in values_by_key.items():
        if values:
            mean = float(math.fsum(values) / len(values))
            median = float(statistics.median(values))
            result[key] = {'mean': mean, 'median': median}
        else:
            result[key] = {'mean': None, 'median': None}
