A few things to note:
- A key is registered as soon as it appears in any record, even if its value there is null or non-numeric. That is how a key with no numeric values ends up with `None` statistics instead of being left out.
- `true` and `false` become Python `bool`, which is technically a subclass of `int`. They are excluded explicitly so they don't count as 1 and 0.
- Elements of the list that aren't objects are skipped. Input that isn't a list at all raises a `ValueError`.

## Approach

1. **Collect the columns** of each table from the union of keys across its rows. A row may omit a key, so one row isn't enough.
2. **Standardize table 1 before joining.** The statistics come from table 1's own rows, so the join can't distort the mean or standard deviation. Missing values are skipped. A column with zero spread becomes 0.
3. **Outer-join on `id`.** Every id from either table appears. An id found in only one table gets `None` for the other table's columns.
4. **Sort by `id`** and return rows that contain every column.

## Code

```python
import math


def merge_and_standardize(rows1, rows2):
    def is_missing(v):
        return v is None or (isinstance(v, float) and math.isnan(v))

    def columns(rows):
        cols = []
        seen = set()
        for r in rows:
            for k in r:
                if k != 'id' and k not in seen:
                    seen.add(k)
                    cols.append(k)
        return cols

    cols1 = columns(rows1)
    cols2 = columns(rows2)

    # --- standardize table 1's feature columns (population std, ignore missing)
    stats = {}
    for c in cols1:
        vals = [r[c] for r in rows1 if not is_missing(r.get(c))]
        if vals:
            mean = sum(vals) / len(vals)
            std = math.sqrt(sum((v - mean) ** 2 for v in vals) / len(vals))
        else:
            mean, std = None, None
        stats[c] = (mean, std)

    def standardize(row):
        out = {}
        for c in cols1:
            v = row.get(c)
            if is_missing(v):
                out[c] = None
            else:
                mean, std = stats[c]
                out[c] = 0.0 if std == 0 else (v - mean) / std
        return out

    # --- group rows by id
    by_id1, by_id2 = {}, {}
    for r in rows1:
        by_id1.setdefault(r['id'], []).append(standardize(r))
    for r in rows2:
        by_id2.setdefault(r['id'], []).append(
            {c: (None if is_missing(r.get(c)) else r.get(c)) for c in cols2}
        )

    empty1 = {c: None for c in cols1}
    empty2 = {c: None for c in cols2}

    # --- full outer join
    result = []
    for id_ in sorted(set(by_id1) | set(by_id2)):
        left = by_id1.get(id_, [empty1])
        right = by_id2.get(id_, [empty2])
        for l in left:
            for r in right:
                row = {'id': id_}
                row.update(l)
                row.update(r)
                result.append(row)
    return result
```

## Example

```python
>>> merge_and_standardize([{'id': 1, 'a': 1.0}, {'id': 2, 'a': 3.0}],
...                       [{'id': 2, 'b': 5.0}, {'id': 3, 'b': 7.0}])
[{'id': 1, 'a': -1.0, 'b': None}, {'id': 2, 'a': 1.0, 'b': 5.0}, {'id': 3, 'a': None, 'b': 7.0}]
```

Column `a` has values 1 and 3, so its mean is 2 and its population standard deviation is 1. That gives -1 and 1. Id 3 exists only in table 2, so its `a` is `None`.

## Edge cases

- **Missing values:** a value counts as missing if it is `None`, `NaN`, or the key is absent. Missing values are skipped in the statistics and come out as `None`.
- **Constant columns:** a column with standard deviation 0 becomes `0.0` in every non-missing cell.
- **All-missing columns:** a column with no values at all stays `None` throughout.
- **Duplicate ids:** if an id repeats within a table, the join pairs every matching row from one table with every matching row from the other, as an SQL outer join does. Standardization still uses each table-1 row exactly once.

```python
import math


def merge_and_standardize(rows1, rows2):
    """
    Outer-join two tables (lists of dicts) on 'id'.

    - Feature columns of the first table are z-scored (mean 0, population
      std 1). Statistics are computed over table 1's own rows, before the
      join, and missing values are ignored. A constant column becomes 0.0.
    - Feature columns of the second table are left unchanged.
    - Every output row contains 'id' plus all columns of both tables, with
      None where a value is missing.
    - Output is sorted by id.
    """

    def is_missing(v):
        return v is None or (isinstance(v, float) and math.isnan(v))

    def columns(rows):
        # Ordered union of keys (excluding 'id'), so rows may be ragged.
        seen = {}
        for r in rows:
            for k in r:
                if k != 'id':
                    seen.setdefault(k, None)
        return list(seen)

    cols1 = columns(rows1)
    cols2 = columns(rows2)

    # Column statistics for table 1, ignoring missing values.
    stats = {}
    for c in cols1:
        vals = [float(r[c]) for r in rows1 if not is_missing(r.get(c))]
        if not vals:
            stats[c] = None  # all missing: stays None
            continue
        n = len(vals)
        mean = sum(vals) / n
        if max(vals) == min(vals):
            # Constant column. Checked exactly so that floating-point
            # noise in the mean can't produce a tiny nonzero std.
            std = 0.0
        else:
            std = math.sqrt(sum((v - mean) ** 2 for v in vals) / n)
        stats[c] = (mean, std)

    def standardize(c, v):
        if is_missing(v) or stats[c] is None:
            return None
        mean, std = stats[c]
        return 0.0 if std == 0 else (float(v) - mean) / std

    # Group rows by id. Lists handle duplicate ids
    # (the outer join then yields all combinations).
    left = {}
    for r in rows1:
        rec = {c: standardize(c, r.get(c)) for c in cols1}
        left.setdefault(r['id'], []).append(rec)

    right = {}
    for r in rows2:
        rec = {c: (None if is_missing(r.get(c)) else r.get(c)) for c in cols2}
        right.setdefault(r['id'], []).append(rec)

    empty1 = {c: None for c in cols1}
    empty2 = {c: None for c in cols2}

    result = []
    for id_ in sorted(set(left) | set(right)):
        for l in left.get(id_, [empty1]):
            for rr in right.get(id_, [empty2]):
                row = {'id': id_}
                row.update(l)
                row.update(rr)
                result.append(row)
    return result
```

Example:

```python
>>> merge_and_standardize([{'id': 1, 'a': 1.0}, {'id': 2, 'a': 3.0}],
...                       [{'id': 2, 'b': 5.0}, {'id': 3, 'b': 7.0}])
[{'id': 1, 'a': -1.0, 'b': None}, {'id': 2, 'a': 1.0, 'b': 5.0}, {'id': 3, 'a': None, 'b': 7.0}]
```

Design choices:
- **Order of operations:** standardization uses only table 1's values, computed before the join. The None rows that the join adds therefore don't affect the mean or standard deviation.
- **Missing values:** a value counts as missing if the key is absent, the value is `None`, or the value is a float NaN. Missing values are skipped when computing statistics and become `None` in the output. A column that is entirely missing stays `None`.
- **Constant columns:** these become `0.0` instead of causing a division by zero.
- **Duplicate ids:** these follow standard outer-join behavior, producing one row per matching pair. Ids must be mutually comparable so they can be sorted.

```python
from datetime import datetime
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError


def publication_hour_stats(articles, timezone):
    """
    Group articles by category and compute statistics on the hour of day
    (in the given IANA timezone) at which they were published.

    Returns a dict mapping each category to a dict with the keys
    'count', 'mean', 'min' and 'max' of the publication hours.

    Raises ValueError if `articles` is empty, if an article is missing
    'category' or 'published_time', if a timestamp is invalid or has no
    UTC offset, or if the timezone is unknown.
    """
    if not articles:
        raise ValueError("articles list must not be empty")

    try:
        tz = ZoneInfo(timezone)
    except (ZoneInfoNotFoundError, ValueError, TypeError) as exc:
        raise ValueError(f"Unknown timezone: {timezone!r}") from exc

    hours_by_category = {}

    for i, article in enumerate(articles):
        if not isinstance(article, dict):
            raise ValueError(f"Article at index {i} is not a dict")
        for key in ("category", "published_time"):
            if key not in article:
                raise ValueError(f"Article at index {i} is missing required key {key!r}")

        raw = article["published_time"]
        if not isinstance(raw, str):
            raise ValueError(f"Article at index {i} has a non-string 'published_time'")

        # Python < 3.11 fromisoformat does not accept a trailing 'Z'
