import math


def standardized_tensor_product(P, T):
    """
    For each j in range(n), compute the m x p matrix product P @ T[:, j, :],
    flatten it row by row, and use it as row j of an n-row table.
    Then standardise every column of the table to zero mean and unit
    variance, using the population standard deviation. A column with
    zero variance becomes all zeros.

    P : m x k matrix (list of lists of numbers)
    T : k x n x p tensor (nested lists)

    Returns a list of n lists, each holding m*p floats.
    """
    # ---- validate P ----
    if not P or not isinstance(P, (list, tuple)):
        raise ValueError("P must be a non-empty matrix")
    if any(not isinstance(row, (list, tuple)) for row in P):
        raise ValueError("P must be a list of lists")
    k = len(P[0])
    if k == 0:
        raise ValueError("P must have at least one column")
    if any(len(row) != k for row in P):
        raise ValueError("P must be rectangular")
    m = len(P)

    # ---- validate T ----
    if not T or not isinstance(T, (list, tuple)):
        raise ValueError("T must be a non-empty tensor")
    if any(not isinstance(s, (list, tuple)) for s in T):
        raise ValueError("T must be a 3-D nested list")
    n = len(T[0])
    if n == 0:
        raise ValueError("T must not be empty along its second axis")
    if any(len(s) != n for s in T):
        raise ValueError("T must have a consistent shape")
    if any(not isinstance(r, (list, tuple)) for s in T for r in s):
        raise ValueError("T must be a 3-D nested list")
    p = len(T[0][0])
    if p == 0:
        raise ValueError("T must not be empty along its third axis")
    if any(len(r) != p for s in T for r in s):
        raise ValueError("T must have a consistent shape")

    # ---- dimension compatibility ----
    if len(T) != k:
        raise ValueError(
            f"Dimension mismatch: P has {k} columns but T's first dimension is {len(T)}"
        )

    # ---- build the n x (m*p) table ----
    table = []
    for j in range(n):
        row = []
        for i in range(m):
            for c in range(p):
                total = 0.0
                for t in range(k):
                    total += float(P[i][t]) * float(T[t][j][c])
                row.append(total)
        table.append(row)

    # ---- standardise each column (population std) ----
    ncols = m * p
    for col in range(ncols):
        values = [table[r][col] for r in range(n)]
        mean = sum(values) / n
        var = sum((v - mean) ** 2 for v in values) / n
        std = math.sqrt(var)
        scale = max(1.0, max(abs(v) for v in values))
        if std <= 1e-12 * scale:
            for r in range(n):
                table[r][col] = 0.0
        else:
            for r in range(n):
                table[r][col] = (table[r][col] - mean) / std

    return table
```

