def standardized_tensor_product(P, T):
    """
    For each j, compute P @ T[:, j, :] (an m x p matrix), flatten it row by row,
    and use it as row j of an n-row table. Then standardise each column to zero
    mean and unit (population) variance. Zero-variance columns become all zeros.
    """
    # ---- validation of P ----
    if not P or not isinstance(P, (list, tuple)):
        raise ValueError("P must be a non-empty matrix")
    m = len(P)
    if not P[0]:
        raise ValueError("P must be a non-empty matrix")
    k = len(P[0])
    if any(len(row) != k for row in P):
        raise ValueError("P must be a rectangular matrix")

    # ---- validation of T ----
    if not T or not isinstance(T, (list, tuple)):
        raise ValueError("T must be a non-empty tensor")
    if not T[0]:
        raise ValueError("T must be a non-empty tensor")
    n = len(T[0])
    if not T[0][0]:
        raise ValueError("T must be a non-empty tensor")
    p = len(T[0][0])
    for slab in T:
        if len(slab) != n or any(len(row) != p for row in slab):
            raise ValueError("T must be a regular k x n x p tensor")

    if len(T) != k:
        raise ValueError(
            f"Dimension mismatch: P has {k} columns but T's first dimension is {len(T)}"
        )

    # ---- build the table ----
    table = []
    for j in range(n):
        flat = []
        for i in range(m):
            Pi = P[i]
            for c in range(p):
                s = 0.0
                for t in range(k):
                    s += Pi[t] * T[t][j][c]
                flat.append(float(s))
        table.append(flat)

    # ---- standardise columns ----
    ncols = m * p
    for c in range(ncols):
        col = [table[r][c] for r in range(n)]
        if all(v == col[0] for v in col):
            for r in range(n):
                table[r][c] = 0.0
            continue
        mean = sum(col) / n
        var = sum((v - mean) ** 2 for v in col) / n
        std = math.sqrt(var)
        if std == 0.0:
            for r in range(n):
                table[r][c] = 0.0
        else:
            for r in range(n):
                table[r][c] = (col[r] - mean) / std

