import math


def standardized_tensor_product(P, T):
    """
    For an m x k matrix P and a k x n x p tensor T, build an n-row table whose
    row j is (P @ T[:, j, :]) flattened row by row (length m*p). Then
    standardise each column to zero mean and unit (population) variance.
    Columns with zero variance become all zeros.
    """
    # ---- validate P ----
    if not P or not isinstance(P, (list, tuple)):
        raise ValueError("P must be a non-empty matrix")
    m = len(P)
    if not P[0]:
        raise ValueError("P must be a non-empty matrix")
    k = len(P[0])
    for row in P:
        if not isinstance(row, (list, tuple)) or len(row) != k:
            raise ValueError("P must be a rectangular matrix")

    # ---- validate T ----
    if not T or not isinstance(T, (list, tuple)):
        raise ValueError("T must be a non-empty tensor")
    if not T[0] or not isinstance(T[0], (list, tuple)):
        raise ValueError("T must be a non-empty tensor")
    if not T[0][0] or not isinstance(T[0][0], (list, tuple)):
        raise ValueError("T must be a non-empty tensor")
    if len(T) != k:
        raise ValueError(
            f"Dimension mismatch: P has {k} columns but T's first dimension is {len(T)}"
        )
    n = len(T[0])
    p = len(T[0][0])
    for slab in T:
        if not isinstance(slab, (list, tuple)) or len(slab) != n:
            raise ValueError("T must be a regular (non-ragged) 3-D tensor")
        for vec in slab:
            if not isinstance(vec, (list, tuple)) or len(vec) != p:
                raise ValueError("T must be a regular (non-ragged) 3-D tensor")

    # ---- build the n x (m*p) table ----
    table = []
    for j in range(n):
        row = []
        for a in range(m):
            for c in range(p):
                s = 0.0
                for b in range(k):
                    s += P[a][b] * T[b][j][c]
                row.append(float(s))
        table.append(row)

    # ---- standardise columns (population std) ----
    ncols = m * p
    for col in range(ncols):
        values = [table[r][col] for r in range(n)]
        first = values[0]
        if all(v == first for v in values):
            for r in range(n):
                table[r][col] = 0.0
            continue
        mean = sum(values) / n
        var = sum((v - mean) ** 2 for v in values) / n
        std = math.sqrt(var)
        if std == 0.0:
            for r in range(n):
                table[r][col] = 0.0
        else:
            for r in range(n):
                table[r][col] = (values[r] - mean) / std

    return table
