import math


def standardized_tensor_product(P, T):
    """
    For each j in range(n), compute the m x p matrix product P @ T[:, j, :]
    and flatten it row by row into row j of a table. Then standardise every
    column of that table to zero mean and unit (population) variance.
    Columns with zero variance become all zeros.

    P : m x k matrix (list of lists of numbers)
    T : k x n x p tensor (nested lists)
    Returns: n x (m*p) list of lists of floats.
    """
    # ---- validation -------------------------------------------------------
    if not P or not isinstance(P, (list, tuple)):
        raise ValueError("P must be a non-empty matrix")
    if not T or not isinstance(T, (list, tuple)):
        raise ValueError("T must be a non-empty tensor")

    m = len(P)
    k = len(P[0]) if isinstance(P[0], (list, tuple)) else 0
    if k == 0:
        raise ValueError("P must be a non-empty matrix")
    for row in P:
        if not isinstance(row, (list, tuple)) or len(row) != k:
            raise ValueError("P must be a rectangular matrix")

    if len(T) != k:
        raise ValueError(
            f"Dimension mismatch: P has {k} columns but T has first dimension {len(T)}"
        )

    first = T[0]
    if not isinstance(first, (list, tuple)) or len(first) == 0:
        raise ValueError("T must be a non-empty tensor")
    n = len(first)
    if not isinstance(first[0], (list, tuple)) or len(first[0]) == 0:
        raise ValueError("T must be a non-empty tensor")
    p = len(first[0])

    for slab in T:
        if not isinstance(slab, (list, tuple)) or len(slab) != n:
            raise ValueError("T must be a regular k x n x p tensor")
        for vec in slab:
            if not isinstance(vec, (list, tuple)) or len(vec) != p:
                raise ValueError("T must be a regular k x n x p tensor")

    # ---- build the table --------------------------------------------------
    table = []
    for j in range(n):
        row = []
        for i in range(m):
            Pi = P[i]
            for c in range(p):
                s = 0.0
                for t in range(k):
                    s += Pi[t] * T[t][j][c]
                row.append(float(s))
        table.append(row)

    # ---- standardise columns ---------------------------------------------
    ncols = m * p
    for c in range(ncols):
        col = [table[r][c] for r in range(n)]
        if max(col) == min(col):
            # zero variance (checked exactly to avoid floating-point noise)
            for r in range(n):
                table[r][c] = 0.0
            continue
        mean = math.fsum(col) / n
        var = math.fsum((x - mean) ** 2 for x in col) / n
        std = math.sqrt(var)
        if std == 0.0:
            for r in range(n):
                table[r][c] = 0.0
        else:
            for r in range(n):
                table[r][c] = (col[r] - mean) / std

    return table
