import math


def standardized_tensor_product(P, T):
    """
    P: m x k matrix (list of lists)
    T: k x n x p tensor (nested lists)

    Row j of the result is (P @ T[:, j, :]), an m x p matrix flattened
    row by row. Each column is then standardised to zero mean and unit
    population variance. A constant column becomes all zeros.
    """
    # Check that neither input is empty
    if not P or not isinstance(P, (list, tuple)) or not P[0]:
        raise ValueError("P must be a non-empty matrix")
    if not T or not isinstance(T, (list, tuple)) or not T[0] or not T[0][0]:
        raise ValueError("T must be a non-empty 3-D tensor")

    m = len(P)
    k = len(P[0])
    if any(len(row) != k for row in P):
        raise ValueError("P must be rectangular")

    if len(T) != k:
        raise ValueError(
            f"Dimension mismatch: P has {k} columns but T has first dimension {len(T)}"
        )

    n = len(T[0])
    p = len(T[0][0])
    for a in range(k):
        if len(T[a]) != n:
            raise ValueError("T must be a regular k x n x p tensor")
        for j in range(n):
            if len(T[a][j]) != p:
                raise ValueError("T must be a regular k x n x p tensor")

    # Row j is P @ T[:, j, :], flattened row by row
    table = []
    for j in range(n):
        row = []
        for i in range(m):
            for c in range(p):
                s = 0
                for a in range(k):
                    s += P[i][a] * T[a][j][c]
                row.append(float(s))
        table.append(row)

    # Standardise each column using the population standard deviation
    ncols = m * p
    result = [[0.0] * ncols for _ in range(n)]
    for col in range(ncols):
        values = [table[r][col] for r in range(n)]
        if all(v == values[0] for v in values):
            continue  # constant column stays all zeros
        mean = sum(values) / n
        var = sum((v - mean) ** 2 for v in values) / n
        std = math.sqrt(var)
        if std == 0:
            continue
        for r in range(n):
            result[r][col] = (values[r] - mean) / std

    return result
