```python
import csv
import io
import math


def fill_missing_with_column_mean(csv_text):
    """
    Parse CSV text (with a header row) into a dict mapping column -> list of values.

    - Numeric columns (every non-empty cell parses as a number) hold floats,
      and empty cells are filled with the mean of the column's present values.
    - Other columns hold strings, and empty cells become None.
    - A column with no non-empty values at all becomes all None.
    - Empty input returns {}.
    """
    if not csv_text or not csv_text.strip():
        return {}

    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows:
        return {}

    header = rows[0]
    if header:
        header[0] = header[0].lstrip('\ufeff')  # tolerate a UTF-8 BOM
    ncols = len(header)

    # Normalise data rows to the header width.
    data = []
    for row in rows[1:]:
        if not row and ncols != 1:
            # Blank line: skip it. With a single column, a blank line is
            # the only way to write an empty cell, so keep it as a row.
            continue
        row = (row + [''] * ncols)[:ncols]
        data.append(row)

    def is_missing(cell):
        return cell.strip() == ''

    def to_float(cell):
        try:
            return float(cell)
        except ValueError:
            return None

    result = {}
    for j, name in enumerate(header):
        cells = [row[j] for row in data]
        present = [c for c in cells if not is_missing(c)]

        if not present:
            result[name] = [None] * len(cells)
            continue

        parsed = [to_float(c) for c in present]
        if all(p is not None for p in parsed):
            mean = math.fsum(parsed) / len(parsed)
            result[name] = [mean if is_missing(c) else float(c) for c in cells]
        else:
            result[name] = [None if is_missing(c) else c for c in cells]

    return result
```

