        return (type(v).__name__, str(v))

    result = {}
    for name, col in columns.items():
        # Step 1: replacements
        col = [replace(v) for v in col]

        # Step 2: encode string-containing columns
        if any(isinstance(v, str) for v in col):
            distinct = list(dict.fromkeys(col))  # preserve uniqueness
            try:
                ordered = sorted(distinct)
            except TypeError:
                ordered = sorted(distinct, key=sort_key_fallback)
            codes = {v: i for i, v in enumerate(ordered)}
            col = [codes[v] for v in col]

        # Validate numeric content
        numeric = []
        for v in col:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                if isinstance(v, bool):
                    numeric.append(float(v))
                    continue
                raise ValueError(
                    f"column {name!r} contains non-numeric value {v!r}"
                )
            numeric.append(float(v))

        # Step 3: standardize
        n = len(numeric)
        if n < 2:
            result[name] = [0.0] * n
            continue
        mean = sum(numeric) / n
        var = sum((x - mean) ** 2 for x in numeric) / (n - 1)
        std = math.sqrt(var)
        if std == 0:
            result[name] = [0.0] * n
        else:
            result[name] = [(x - mean) / std for x in numeric]

