import math


def encode_and_standardize(data, replacements):
    """
    Preprocess a column-oriented table.

    Steps:
      1. Replace any value that is a key of `replacements` with its mapped value.
      2. Encode every column containing strings as integer codes 0..k-1, numbering
         the distinct values in sorted order.
      3. Standardize every column: (x - mean) / sample_std.

    Returns a dict {column_name: [standardized floats]} in the original column order.

    Edge cases:
      * Constant columns (std == 0) and single-row columns (sample std undefined)
        are returned as all 0.0.
      * Empty columns are returned as empty lists.

    Raises:
      ValueError if `data` is not a dict, columns have different lengths,
      or a column contains values that cannot be treated as numbers.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")
    if replacements is None:
        replacements = {}

    # Check that all columns have equal length
    lengths = {len(col) for col in data.values()}
    if len(lengths) > 1:
        raise ValueError("all columns must have the same length")

    def replace(v):
        try:
            return replacements[v] if v in replacements else v
        except TypeError:  # unhashable value, cannot be a key
            return v

    def sorted_distinct(values):
        distinct = set(values)
        try:
            return sorted(distinct)
        except TypeError:
            # Mixed, mutually incomparable types: deterministic fallback ordering
            return sorted(distinct, key=lambda v: (type(v).__name__, str(v)))

    result = {}
    for name, column in data.items():
        # 1. Replacement
        values = [replace(v) for v in column]

        # 2. Encoding of string-containing columns
        if any(isinstance(v, str) for v in values):
            codes = {v: i for i, v in enumerate(sorted_distinct(values))}
            values = [codes[v] for v in values]

        # Convert to floats
        try:
            nums = [float(v) for v in values]
        except (TypeError, ValueError):
            raise ValueError(f"column {name!r} contains non-numeric values")

        # 3. Standardization
        n = len(nums)
        if n == 0:
            result[name] = []
            continue
        if n == 1:
            result[name] = [0.0]
            continue

        mean = sum(nums) / n
        var = sum((x - mean) ** 2 for x in nums) / (n - 1)
        std = math.sqrt(var)
        if std == 0:
            result[name] = [0.0] * n
        else:
            result[name] = [(x - mean) / std for x in nums]

    return result
