import math
from numbers import Real


def correlation_without_column(data, column):
    """Return the Pearson correlation matrix of the numeric columns of `data`,
    excluding `column`, as a dict of dicts. Return None if no numeric columns remain."""
    if not data:
        return None

    def is_number(v):
        # Real numbers only; bools are excluded even though bool is a subclass of int.
        return isinstance(v, Real) and not isinstance(v, bool)

    # Keep columns other than `column` whose values are all numbers.
    numeric = {
        name: [float(v) for v in values]
        for name, values in data.items()
        if name != column and all(is_number(v) for v in values)
    }
    if not numeric:
        return None

    # Precompute each column's deviations from its mean and its sum of squared deviations.
    stats = {}
    for name, values in numeric.items():
        n = len(values)
        if n == 0:
            stats[name] = (None, 0.0)
            continue
        mean = math.fsum(values) / n
        dev = [v - mean for v in values]
        ss = math.fsum(d * d for d in dev)
        stats[name] = (dev, ss)

    def pearson(x, y):
        dx, ssx = stats[x]
        dy, ssy = stats[y]
        # Undefined for fewer than 2 values, zero variance, or NaN values.
        if dx is None or len(dx) < 2 or not ssx > 0 or not ssy > 0:
            return float("nan")
        if x == y:
            return 1.0
        sxy = math.fsum(a * b for a, b in zip(dx, dy))
        r = sxy / math.sqrt(ssx * ssy)
        # Clamp tiny floating-point overshoots.
        return max(-1.0, min(1.0, r))

    names = list(numeric)
    result = {x: {} for x in names}
    for i, x in enumerate(names):
        for y in names[i:]:
            r = pearson(x, y)
            result[x][y] = r
            result[y][x] = r

    # Keep the inner dicts in the original column order.
    return {x: {y: result[x][y] for y in names} for x in names}
```

