- If `column` isn't in `data`, nothing is dropped.
- A column with zero variance or fewer than two values has an undefined correlation, so it gets `nan`. This also applies to its diagonal entry, which matches pandas' behavior.

```python
import math
from numbers import Real


def _is_number(v):
    # bools are a subclass of int in Python, but they are not "numbers" here
    return isinstance(v, Real) and not isinstance(v, bool)


def _pearson(xs, ys):
    # Use only positions where both values are present (not NaN)
    pairs = [(float(x), float(y)) for x, y in zip(xs, ys)
             if not (math.isnan(x) or math.isnan(y))]
    n = len(pairs)
    if n < 2:
        return float('nan')

    mean_x = sum(p[0] for p in pairs) / n
    mean_y = sum(p[1] for p in pairs) / n

    sxy = sxx = syy = 0.0
    for x, y in pairs:
        dx = x - mean_x
        dy = y - mean_y
        sxy += dx * dy
        sxx += dx * dx
        syy += dy * dy

    divisor = math.sqrt(sxx * syy)
    if divisor == 0:
        # A constant column has an undefined correlation
        return float('nan')

    r = sxy / divisor
    # Guard against tiny floating-point overshoot
    return max(-1.0, min(1.0, r))


def correlation_without_column(data, column):
    if not data:
        return None

    numeric = {
        name: list(values)
        for name, values in data.items()
        if name != column and all(_is_number(v) for v in values)
    }

    if not numeric:
        return None

    names = list(numeric)
    result = {name: {} for name in names}
    for i, x in enumerate(names):
        for y in names[i:]:
            r = _pearson(numeric[x], numeric[y])
            result[x][y] = r
            result[y][x] = r

    # Restore column order within each inner dict
    return {x: {y: result[x][y] for y in names} for x in names}
```

