Notes on behavior:
- **Dropping the column:** The column named `column` is removed if present. If it is not present, nothing is dropped.
- **Numeric check:** A column is kept only if every value is a real number. Strings, `None`, and booleans all cause the column to be ignored.
- **NaN values:** Pairs containing a NaN are skipped when computing each correlation.
- **Undefined correlations:** A constant column has zero variance, so its correlation is reported as `nan`. The same applies when fewer than two valid pairs remain.
- **No numeric columns:** If none remain, including when `data` is empty, the function returns `None`.

```python
import math
from numbers import Real


def correlation_without_column(data, column):
    """
    Drop `column` from `data` (if present), keep only columns whose values are
    all real numbers, and return the Pearson correlation matrix of those columns
    as a dict of dicts. Returns None if no numeric columns remain.

    Pairs involving a column with zero variance (or fewer than 2 values) get NaN.
    """
    if not data:
        return None

    def is_number(v):
        # bools are technically ints in Python, but they are not treated as numbers here
        return isinstance(v, Real) and not isinstance(v, bool)

    # Select numeric columns, excluding the dropped one (input is not mutated)
    numeric = {
        name: [float(v) for v in values]
        for name, values in data.items()
        if name != column and all(is_number(v) for v in values)
    }

    if not numeric:
        return None

    # Precompute deviations from the mean and the sum of squared deviations
    deviations = {}
    sum_sq = {}
    for name, values in numeric.items():
        n = len(values)
        if n == 0:
            deviations[name] = []
            sum_sq[name] = 0.0
            continue
        mean = math.fsum(values) / n
        devs = [v - mean for v in values]
        deviations[name] = devs
        sum_sq[name] = math.fsum(d * d for d in devs)

    def corr(x, y):
        dx, dy = deviations[x], deviations[y]
        if len(dx) < 2 or sum_sq[x] == 0 or sum_sq[y] == 0:
            return float('nan')
        if x == y:
            return 1.0
        cov = math.fsum(a * b for a, b in zip(dx, dy))
        r = cov / math.sqrt(sum_sq[x] * sum_sq[y])
        # Guard against tiny floating-point overshoot
        return max(-1.0, min(1.0, r))

    names = list(numeric)
    result = {x: {} for x in names}
    for i, x in enumerate(names):
        for y in names[i:]:
            r = corr(x, y)
            result[x][y] = r
            result[y][x] = r

    # Rebuild inner dicts so keys follow the original column order
    return {x: {y: result[x][y] for y in names} for x in names}
```

