_TOKEN_RE = re.compile(r"(?u)\b\w\w+\b")


def tfidf_scores_for_question_articles(titles, contents):
    """
    Select articles whose title contains 'how' or 'what' (case-insensitive,
    substring match), compute TF-IDF over their bodies, and return a dict
    mapping each word to the sum of its TF-IDF scores across those articles.

    - Tokens: lowercased runs of two or more word characters.
    - TF: raw term counts.
    - IDF: ln((1 + N) / (1 + df)) + 1  (smoothed).
    - Each article's vector is L2-normalised.
    """
    if len(titles) != len(contents):
        raise ValueError("titles and contents must have the same length")

    # Pick question-like articles
    selected = [
        body for title, body in zip(titles, contents)
        if "how" in title.lower() or "what" in title.lower()
    ]
    if not selected:
        return {}

    # Tokenise and count terms per document
    doc_counts = [Counter(_TOKEN_RE.findall(body.lower())) for body in selected]

    # Document frequencies
    df = Counter()
    for counts in doc_counts:
        df.update(counts.keys())

    if not df:
        return {}

    n_docs = len(doc_counts)
    idf = {term: math.log((1 + n_docs) / (1 + d)) + 1 for term, d in df.items()}

    # Accumulate L2-normalised TF-IDF scores
    totals = {term: 0.0 for term in df}
    for counts in doc_counts:
        weights = {term: c * idf[term] for term, c in counts.items()}
        norm = math.sqrt(sum(w * w for w in weights.values()))
        if norm == 0:
            continue
        for term, w in weights.items():
            totals[term] += w / norm

    return {term: totals[term] for term in sorted(totals)}
