    selected = [
        body for title, body in zip(titles, contents)
        if "how" in title.lower() or "what" in title.lower()
    ]
    if not selected:
        return {}

    token_re = re.compile(r"\b\w\w+\b")
    doc_counts = [Counter(token_re.findall(body.lower())) for body in selected]

    # Document frequency of each term.
    n_docs = len(doc_counts)
    df = Counter()
    for counts in doc_counts:
        df.update(counts.keys())

    idf = {
        term: math.log((1 + n_docs) / (1 + freq)) + 1
        for term, freq in df.items()
    }

    # Weight, normalise and accumulate.
    totals = {term: 0.0 for term in df}
    for counts in doc_counts:
        weights = {term: tf * idf[term] for term, tf in counts.items()}
        norm = math.sqrt(sum(w * w for w in weights.values()))
        if norm == 0:
            continue  # empty document contributes nothing
        for term, w in weights.items():
            totals[term] += w / norm

    return dict(sorted(totals.items()))
