from html.parser import HTMLParser


class _TableExtractor(HTMLParser):
    """Collects the rows/cells of the first <table> whose id matches."""

    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)  # decodes entities in text
        self.table_id = table_id
        self.found = False
        self.done = False
        self.table_depth = 0      # number of currently open <table> elements
        self.target_depth = None  # depth of the target table
        self.rows = []            # list of rows; each row is a list of cell strings
        self.current_row = None
        self.current_cell = None  # list of text fragments of the open cell
        self.skip_depth = 0       # inside <script>/<style>

    # helpers
    def _in_target_level(self):
        return (self.found and not self.done
                and self.table_depth == self.target_depth)

    def _close_cell(self):
        if self.current_cell is not None:
            text = "".join(self.current_cell).strip()
            if self.current_row is None:      # cell without a <tr>: implied row
                self.current_row = []
            self.current_row.append(text)
            self.current_cell = None

    def _close_row(self):
        self._close_cell()
        if self.current_row is not None:
            self.rows.append(self.current_row)
            self.current_row = None

    # parser callbacks
    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in ("script", "style"):
            self.skip_depth += 1
            return
        if tag == "table":
            self.table_depth += 1
            if not self.found:
                ident = dict(attrs).get("id")
                if ident == self.table_id:
                    self.found = True
                    self.target_depth = self.table_depth
            return
        if not self._in_target_level():
            return
        if tag == "tr":
            self._close_row()
            self.current_row = []
        elif tag in ("td", "th"):
            self._close_cell()
            if self.current_row is None:
                self.current_row = []
            self.current_cell = []
        elif tag in ("thead", "tbody", "tfoot"):
            self._close_row()

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in ("script", "style"):
            if self.skip_depth:
                self.skip_depth -= 1
            return
        if tag == "table":
            if self._in_target_level():
                self._close_row()
                self.done = True
            if self.table_depth:
                self.table_depth -= 1
            return
        if not self._in_target_level():
            return
        if tag in ("td", "th"):
            self._close_cell()
        elif tag == "tr":
            self._close_row()
        elif tag in ("thead", "tbody", "tfoot"):
            self._close_row()

    def handle_data(self, data):
        if self.skip_depth:
            return
        if self.found and not self.done and self.current_cell is not None:
            self.current_cell.append(data)

    def finish(self):
        self.close()
        if self.found and not self.done:   # unterminated target table
            self._close_row()
            self.done = True


def html_table_records(html, table_id):
    parser = _TableExtractor(table_id)
    parser.feed(html)
    parser.finish()

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r} found")

    rows = parser.rows
    if not rows:
        return []

    headers = rows[0]
    records = []
    for row in rows[1:]:
        record = {}
        for i, header in enumerate(headers):
            record[header] = row[i] if i < len(row) else ""
        records.append(record)
    return records
```

Notes on behavior:
- Tags inside cells are dropped. Entities like `&amp;` and `&#39;` are decoded. Cell text is stripped of surrounding whitespace.
- `<thead>`/`<tbody>`/`<tfoot>` are handled. Omitted closing `</td>`, `</th>` and `</tr>` tags (valid HTML) are inferred.
- Rows of tables nested inside the target table are not treated as records. Their text becomes part of the enclosing cell.
- The contents of `<script>` and `<style>` are ignored.
- If a row has fewer cells than there are headers, the missing values are `""`. Extra cells beyond the headers are ignored.
- If several tables share the id, the first one in document order is used.

```python
from html.parser import HTMLParser


class _TableParser(HTMLParser):
    """Collects the rows of the first table whose id matches `table_id`."""

    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)  # decodes entities in text
        self.table_id = table_id
        self.found = False
        self.done = False
        self.depth = 0          # 0 = outside target table, 1 = directly in it, >1 = nested table
        self.rows = []
        self.row = None
        self.cell = None
        self.skip = 0           # inside <script>/<style> within a cell

    def _close_cell(self):
        if self.cell is not None:
            if self.row is None:
                self.row = []
            self.row.append(''.join(self.cell).strip())
            self.cell = None

    def _close_row(self):
        self._close_cell()
        if self.row is not None:
            self.rows.append(self.row)
            self.row = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if self.depth == 0:
            if tag == 'table' and dict(attrs).get('id') == self.table_id:
                self.found = True
                self.depth = 1
            return
        if tag in ('script', 'style'):
            self.skip += 1
            return
        if tag == 'table':
            self.depth += 1
            return
        if self.depth == 1:
            if tag == 'tr':
                # A new row implicitly closes any open cell/row
                self._close_row()
                self.row = []
            elif tag in ('td', 'th'):
                # A new cell implicitly closes any open cell
                self._close_cell()
                if self.row is None:
                    self.row = []
                self.cell = []

    def handle_endtag(self, tag):
        if self.done or self.depth == 0:
            return
        if tag in ('script', 'style'):
            if self.skip:
                self.skip -= 1
            return
        if tag == 'table':
            self.depth -= 1
            if self.depth == 0:
                self._close_row()
                self.done = True
            return
        if self.depth == 1:
            if tag in ('td', 'th'):
                self._close_cell()
            elif tag == 'tr':
                self._close_row()

    def handle_data(self, data):
        # Text anywhere inside a cell (including nested tags/tables) is kept
        if self.depth >= 1 and not self.done and self.cell is not None and not self.skip:
            self.cell.append(data)


def html_table_records(html, table_id):
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r} found")
    if not parser.done:          # unterminated table: flush what we have
        parser._close_row()

    rows = parser.rows
    if not rows:
        return []

    headers = rows[0]
    records = []
    for row in rows[1:]:
        # Pad short rows with '' and ignore cells beyond the header count
        padded = row + [''] * (len(headers) - len(row))
        records.append(dict(zip(headers, padded)))
    return records
```

