...                    "<tr><td>Alice</td><td>25</td></tr>"
...                    "<tr><td>Bob</td><td>30</td></tr></table>", 't')
[{'Name': 'Alice', 'Age': '25'}, {'Name': 'Bob', 'Age': '30'}]
```

How it works:

- **Parsing:** It uses the standard library's `HTMLParser` with `convert_charrefs=True`, so entities like `&amp;` and `&nbsp;` are decoded automatically.
- **Tags and whitespace:** Tags inside cells, such as `<b>`, are dropped and only their text is kept. Surrounding whitespace is then stripped from each cell.
- **Finding the table:** Only the first table with a matching `id` is used. If none matches, it raises `ValueError`.
- **Nested tables:** Their rows and cells are not treated as rows of the target table. Their text becomes part of the enclosing cell's text.
- **Omitted closing tags:** HTML allows `</td>` and `</tr>` to be left out. A new `<tr>`, `<td>` or `<th>` implicitly closes the open cell or row, and so does `</table>`.
- **`<thead>`/`<tbody>`/`<tfoot>`:** These wrappers are handled transparently, and rows are kept in document order.
- **Mismatched row lengths:** Rows shorter than the header row are padded with `''`. Extra cells beyond the headers are ignored.

```python
from html.parser import HTMLParser


class _TableExtractor(HTMLParser):
    """Collects the rows of the first <table> whose id matches table_id."""

    _SECTION_TAGS = {"thead", "tbody", "tfoot"}

    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)  # decodes &amp;, &#39;, etc.
        self.table_id = table_id
        self.found = False        # target table has been seen
        self.capturing = False    # currently inside the target table
        self.done = False         # target table has been closed
        self.nested = 0           # depth of tables nested inside the target
        self.rows = []            # list of rows, each a list of (text, colspan)
        self.row = None           # cells of the row being built
        self.cell = None          # text fragments of the cell being built
        self.colspan = 1

    # Helpers for closing open elements, explicitly or implicitly.
    def _close_cell(self):
        if self.cell is not None:
            self.row.append(("".join(self.cell).strip(), self.colspan))
            self.cell = None

    def _close_row(self):
        self._close_cell()
        if self.row is not None:
            if self.row:          # ignore rows that contain no cells
                self.rows.append(self.row)
            self.row = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if not self.capturing:
            if tag == "table" and dict(attrs).get("id") == self.table_id:
                self.found = self.capturing = True
            return

        if self.nested:                     # inside a nested table: text only
            if tag == "table":
                self.nested += 1
            return

        if tag == "table":                  # nested table starts
            self.nested = 1
        elif tag == "tr":
            self._close_row()
            self.row = []
        elif tag in ("td", "th"):
            self._close_cell()
            if self.row is None:            # cell without an explicit <tr>
                self.row = []
            self.cell = []
            try:
                self.colspan = max(1, int(dict(attrs).get("colspan") or 1))
            except ValueError:
                self.colspan = 1
        elif tag in self._SECTION_TAGS:
            self._close_row()

    def handle_endtag(self, tag):
        if not self.capturing or self.done:
            return

        if self.nested:
            if tag == "table":
                self.nested -= 1
            return

        if tag == "table":
            self._close_row()
            self.capturing = False
            self.done = True
        elif tag in ("td", "th"):
            self._close_cell()
        elif tag == "tr" or tag in self._SECTION_TAGS:
            self._close_row()

    def handle_data(self, data):
        if self.capturing and not self.done and self.cell is not None:
            self.cell.append(data)

    def close(self):
        super().close()
        if self.capturing and not self.done:   # unclosed <table>
            self._close_row()


def _expand(row):
    """Expand colspan so each spanned column gets the cell's text."""
    out = []
    for text, span in row:
        out.extend([text] * span)
    return out


def html_table_records(html, table_id):
    parser = _TableExtractor(table_id)
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r}")
    if not parser.rows:
        return []

    headers = _expand(parser.rows[0])
    records = []
    for row in parser.rows[1:]:
        cells = _expand(row)
        # Missing cells become '', surplus cells are ignored.
        records.append({
            h: (cells[i] if i < len(cells) else "")
            for i, h in enumerate(headers)
        })
    return records
```

