```python
>>> concat_csv_tables(["A,B\n0,3\n1,4\n", "A,B\n2,5\n"])
[{'A': 0, 'B': 3}, {'A': 1, 'B': 4}, {'A': 2, 'B': 5}]
>>> concat_csv_tables(["x,y\n1,a\n", "x,y\n2.5,b\n"])
[{'x': 1.0, 'y': 'a'}, {'x': 2.5, 'y': 'b'}]
```

How it handles the details:

- **Column types are decided across all documents together.** Each document is not converted separately. So if one document has `1` and another has `2.5` in the same column, the whole column becomes floats. If any value in a column is non-numeric, every value in that column stays a string.
- **Integers vs. floats:** a column becomes `int` only if every value parses as an integer. Otherwise it becomes `float` if every value parses as a float.
- **Columns are matched by name.** Documents can list the columns in a different order. The output dicts follow the column order of the first document.
- **Errors:** a `ValueError` is raised in these cases:
  - the input list is empty
  - a document has no header
  - headers don't match across documents
  - a header has duplicate column names
  - a row has the wrong number of fields
- Blank lines are skipped, and a document with only a header contributes no rows.
- Empty fields are treated as non-numeric, so a column with any empty value stays as strings.

```python
import math


def _anova_f(values, labels):
    """One-way ANOVA F-statistic of `values` grouped by `labels`."""
    groups = {}
    for v, g in zip(values, labels):
        groups.setdefault(g, []).append(float(v))

    n = len(values)
    k = len(groups)
    if k < 2 or n - k <= 0:
        return float("nan")

    grand_mean = sum(float(v) for v in values) / n
    ss_between = 0.0
    ss_within = 0.0
    for vals in groups.values():
        m = sum(vals) / len(vals)
        ss_between += len(vals) * (m - grand_mean) ** 2
        ss_within += sum((x - m) ** 2 for x in vals)

    df_between = k - 1
    df_within = n - k
    if ss_within == 0.0:
        # Perfect separation gives an infinite F. No variation at all gives 0.
        return float("inf") if ss_between > 0 else 0.0
    return (ss_between / df_between) / (ss_within / df_within)


def _pearson(x, y):
    n = len(x)
    mx = sum(x) / n
    my = sum(y) / n
    sxy = sum((a - mx) * (b - my) for a, b in zip(x, y))
    sxx = sum((a - mx) ** 2 for a in x)
    syy = sum((b - my) ** 2 for b in y)
    if sxx == 0 or syy == 0:
        return float("nan")
    return sxy / math.sqrt(sxx * syy)


def select_top_features(features, labels):
    names = list(features.keys())
    if len(names) < 2:
        raise ValueError("At least two features are required.")
    for name in names:
        if len(features[name]) != len(labels):
            raise ValueError(f"Feature {name!r} length does not match labels.")

    scores = {name: _anova_f(features[name], labels) for name in names}

    def sort_key(i):
        s = scores[names[i]]
        s = float("-inf") if math.isnan(s) else s
        return -s

    # Stable sort: ties are broken by the order in the dict.
    order = sorted(range(len(names)), key=sort_key)
    top_idx = sorted(order[:2])  # restore dict order
    selected = [names[i] for i in top_idx]

    x = [float(v) for v in features[selected[0]]]
    y = [float(v) for v in features[selected[1]]]
    r = _pearson(x, y)
    corr = [[1.0, r], [r, 1.0]]
    return selected, corr
```

For the example, the F-statistics are a = 8.0, b = 0.5 and c = 9.8. So the two selected features are `a` and `c`, listed in dict order. Their Pearson correlation is 17/√295 ≈ 0.9897782665572. The function returns the full-precision float, so compare with a tolerance (or round) if you need the exact digits shown in the example.

```python
import math
from fractions import Fraction


def mapped_correlation_matrix(data, mapping):
    """
    Replace values in each column using `mapping` (values that are not keys of
    `mapping` are kept), then return the pairwise Pearson correlation matrix as
    a nested dict: result[a][b] == corr(column a, column b).

    Correlations involving a column with zero variance (or fewer than two
    rows) are undefined and reported as float('nan').
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists of values")
    if mapping is None:
        mapping = {}
    if not isinstance(mapping, dict):
        raise ValueError("mapping must be a dict")

    def _replace(v):
        try:
            return mapping[v] if v in mapping else v
        except TypeError:          # unhashable value, so it cannot be a key
            return v

    # Apply the mapping and validate that every value is numeric.
    columns = {}
    length = None
    for name, values in data.items():
        try:
            values = list(values)
        except TypeError:
            raise ValueError(f"column {name!r} is not a sequence of values")
        mapped = [_replace(v) for v in values]
        for v in mapped:
            if isinstance(v, (str, bytes)) or not isinstance(v, (int, float, Fraction)):
                try:
                    float(v)
                except (TypeError, ValueError):
                    raise ValueError(
                        f"column {name!r} contains non-numeric value {v!r} after mapping"
                    )
                if isinstance(v, (str, bytes)):
                    raise ValueError(
                        f"column {name!r} contains non-numeric value {v!r} after mapping"
                    )
        if length is None:
            length = len(mapped)
        elif len(mapped) != length:
            raise ValueError("all columns must have the same length")
        columns[name] = mapped

    names = list(columns)
    n = length or 0

    # Try exact rational arithmetic (avoids rounding noise such as 0.49999999);
    # fall back to floats if any value is not representable (inf, nan, ...).
    try:
        exact = {k: [Fraction(v) for v in vals] for k, vals in columns.items()}
        use_exact = True
    except (TypeError, ValueError, OverflowError):
        use_exact = False

    if use_exact:
        devs = {}
        for k, vals in exact.items():
            mean = sum(vals, Fraction(0)) / n if n else Fraction(0)
            devs[k] = [v - mean for v in vals]
    else:
        devs = {}
        for k, vals in columns.items():
            fvals = [float(v) for v in vals]
            mean = math.fsum(fvals) / n if n else 0.0
            devs[k] = [v - mean for v in fvals]

    def _sum(it):
        return sum(it, Fraction(0)) if use_exact else math.fsum(it)

    var = {k: _sum(d * d for d in devs[k]) for k in names}

    def _exact_sqrt(fr):
        """sqrt of a non-negative Fraction; exact when possible."""
        num, den = fr.numerator, fr.denominator
        rn, rd = math.isqrt(num), math.isqrt(den)
        if rn * rn == num and rd * rd == den:
            return rn / rd
        return math.sqrt(num / den) if num < 10**300 else math.sqrt(float(fr))

    def _corr(a, b):
        if n < 2:
            return float("nan")
        va, vb = var[a], var[b]
        if not va > 0 or not vb > 0:
            return float("nan")
        if a == b:
            return 1.0
        cov = _sum(x * y for x, y in zip(devs[a], devs[b]))
        if use_exact:
            if cov == 0:
                return 0.0
            r = _exact_sqrt(cov * cov / (va * vb))
            r = r if cov > 0 else -r
        else:
            r = cov / math.sqrt(va * vb)
        return float(max(-1.0, min(1.0, r)))

    result = {a: {} for a in names}
    for i, a in enumerate(names):
        for b in names[i:]:
            r = _corr(a, b)
            result[a][b] = r
            result[b][a] = r
    # Rebuild inner dicts so the key order follows the column order.
    return {a: {b: result[a][b] for b in names} for a in names}
```

