>>> mapped_correlation_matrix({'m': ['lo', 'lo', 'hi'], 'n': [5, 3, 5]}, {'lo': 1, 'hi': 2})
{'m': {'m': 1.0, 'n': 0.5}, 'n': {'m': 0.5, 'n': 1.0}}
```

Notes:
- Values that are unhashable (e.g., lists) can't be mapping keys, so they're left as-is (and will then fail the numeric check with a `ValueError`).
- Columns with zero variance yield `nan` correlations, matching the usual convention (e.g., pandas).

```python
import math


def mapped_correlation_matrix(data, mapping):
    """
    Replace values in each column using `mapping`, then compute the pairwise
    Pearson correlation matrix of the columns.

    Parameters
    ----------
    data : dict
        Maps column names to equal-length lists of values.
    mapping : dict
        Values found as keys in `mapping` are replaced by the mapped value.
        All other values are kept unchanged.

    Returns
    -------
    dict
        Nested dict where result[a][b] is the Pearson correlation between
        columns a and b. If a correlation is undefined (for example, a
        constant column or fewer than 2 usable rows), the entry is NaN.

    Raises
    ------
    ValueError
        If `data` is not a dict, if the columns have different lengths,
        or if a value is not numeric after the replacement.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists of values")
    if mapping is None:
        mapping = {}
    if not isinstance(mapping, dict):
        raise ValueError("mapping must be a dict")

    columns = list(data.keys())
    if not columns:
        return {}

    # Validate that every column has the same length.
    lengths = {len(list(data[c])) for c in columns}
    if len(lengths) > 1:
        raise ValueError("all columns in data must have the same length")

    def replace(value):
        try:
            if value in mapping:
                return mapping[value]
        except TypeError:
            # Unhashable values cannot be mapping keys, so keep them as they are.
            pass
        return value

    def to_number(value, col):
        if value is None:
            return None  # treated as a missing value
        if isinstance(value, bool):
            return float(value)
        try:
            num = float(value)
        except (TypeError, ValueError):
            raise ValueError(
                f"column {col!r} contains non-numeric value {value!r} after mapping"
            )
        return None if math.isnan(num) else num

    # Apply the mapping and convert to floats (None marks a missing value).
    mapped = {
        c: [to_number(replace(v), c) for v in data[c]]
        for c in columns
    }

    def pearson(x, y):
        # Use only rows where both values are present (pairwise complete).
        pairs = [(a, b) for a, b in zip(x, y) if a is not None and b is not None]
        n = len(pairs)
        if n < 2:
            return float("nan")
        mean_x = math.fsum(a for a, _ in pairs) / n
        mean_y = math.fsum(b for _, b in pairs) / n
        dx = [a - mean_x for a, _ in pairs]
        dy = [b - mean_y for _, b in pairs]
        sxx = math.fsum(d * d for d in dx)
        syy = math.fsum(d * d for d in dy)
        sxy = math.fsum(a * b for a, b in zip(dx, dy))
        if sxx == 0 or syy == 0:
            return float("nan")
        r = sxy / math.sqrt(sxx * syy)
        # Keep the result inside [-1, 1] despite floating-point error.
        return max(-1.0, min(1.0, r))

    result = {c: {} for c in columns}
    for i, a in enumerate(columns):
        for j in range(i, len(columns)):
            b = columns[j]
            r = pearson(mapped[a], mapped[b])
            if i == j and not math.isnan(r):
                r = 1.0  # a column is perfectly correlated with itself
            result[a][b] = r
            result[b][a] = r

    # Rebuild the inner dicts so their keys follow the original column order.
    return {a: {b: result[a][b] for b in columns} for a in columns}
```

