- `None` and NaN are treated as missing. Each pair of columns uses only the rows where both values are present.
- A correlation that is undefined (a constant column, or fewer than 2 usable rows) is returned as `float('nan')`. This matches the behaviour of pandas `DataFrame.corr()`.

```python
import math


def mapped_correlation_matrix(data, mapping):
    """
    Replace values in each column using `mapping`, then return the pairwise
    Pearson correlation matrix of the columns as a nested dict:
    result[a][b] is the correlation between column a and column b.

    A column with zero variance, or one with fewer than two values, gets
    NaN correlations.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists of values")
    if mapping is None:
        mapping = {}

    def replace(value):
        try:
            if value in mapping:
                return mapping[value]
        except TypeError:  # unhashable value, so it cannot be a mapping key
            pass
        return value

    # Apply the mapping and convert every value to float.
    columns = {}
    length = None
    for name, values in data.items():
        converted = []
        for v in values:
            r = replace(v)
            try:
                converted.append(float(r))
            except (TypeError, ValueError):
                raise ValueError(
                    f"value {v!r} in column {name!r} is not numeric after mapping"
                )
        if length is None:
            length = len(converted)
        elif len(converted) != length:
            raise ValueError("all columns must have the same length")
        columns[name] = converted

    # Center each column and compute its sum of squared deviations.
    centered = {}
    sum_sq = {}
    for name, vals in columns.items():
        n = len(vals)
        mean = math.fsum(vals) / n if n else float("nan")
        dev = [x - mean for x in vals]
        centered[name] = dev
        sum_sq[name] = math.fsum(d * d for d in dev)

    names = list(columns)
    result = {a: {} for a in names}
    for i, a in enumerate(names):
        for b in names[i:]:
            da, db = centered[a], centered[b]
            if len(da) < 2:
                r = float("nan")
            else:
                denom = math.sqrt(sum_sq[a] * sum_sq[b])
                if denom == 0 or math.isnan(denom):
                    r = float("nan")
                else:
                    r = math.fsum(x * y for x, y in zip(da, db)) / denom
                    # Clamp tiny floating-point overshoots.
                    r = max(-1.0, min(1.0, r))
            result[a][b] = r
            result[b][a] = r
    return result
```

