import ast
from html.parser import HTMLParser


class _ScriptCollector(HTMLParser):
    """Collects the raw text content of every <script> element, in order."""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.scripts = []
        self._in_script = False
        self._buffer = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "script":
            self._in_script = True
            self._buffer = []

    def handle_startendtag(self, tag, attrs):
        # A self-closing <script/> has no body. Record it as empty to keep order.
        if tag.lower() == "script":
            self.scripts.append("")

    def handle_endtag(self, tag):
        if tag.lower() == "script" and self._in_script:
            self.scripts.append("".join(self._buffer))
            self._in_script = False
            self._buffer = []

    def handle_data(self, data):
        if self._in_script:
            self._buffer.append(data)

    def handle_entityref(self, name):
        if self._in_script:
            self._buffer.append(f"&{name};")

    def handle_charref(self, name):
        if self._in_script:
            self._buffer.append(f"&#{name};")

    def close(self):
        super().close()
        # Handle a trailing, unterminated <script> element.
        if self._in_script:
            self.scripts.append("".join(self._buffer))
            self._in_script = False
            self._buffer = []


def extract_script_dicts(html):
    """
    Return a list of dicts parsed (as Python literals) from the bodies of
    <script> elements in `html`, in document order. Scripts whose content
    is not a valid Python dict literal are skipped.
    """
    if not html:
        return []

    collector = _ScriptCollector()
    collector.feed(html)
    collector.close()

    results = []
    for body in collector.scripts:
        text = body.strip()
        if not text:
            continue
        try:
            value = ast.literal_eval(text)
        except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
            continue
        if isinstance(value, dict):
            results.append(value)
    return results
```

Example:

```python
>>> extract_script_dicts('<script>{"a": 1}</script><script>var x = 2;</script>')
[{'a': 1}]
```

Notes:
- `html.parser` treats `<script>` contents as raw text, so characters like `<` or `&` inside the script body are preserved as-is.
- `ast.literal_eval` safely evaluates only Python literals (no code execution). The result is accepted only if it is a `dict`, so things like `[1, 2]` or `42` are skipped.
- Leading and trailing whitespace inside the script is ignored. Empty or self-closing scripts are skipped.

