import calendar
import datetime
import re

_WEEKDAYS = {"MON": 0, "TUE": 1, "WED": 2, "THU": 3, "FRI": 4, "SAT": 5, "SUN": 6}


def _parse_start(start_date):
    if not isinstance(start_date, str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", start_date.strip()):
        raise ValueError(f"Invalid start date: {start_date!r} (expected 'YYYY-MM-DD')")
    try:
        return datetime.datetime.strptime(start_date.strip(), "%Y-%m-%d").date()
    except ValueError:
        raise ValueError(f"Invalid start date: {start_date!r}") from None


def _make_rule(freq):
    """Return a function (year, month) -> date or None (None = month not eligible)."""
    if not isinstance(freq, str):
        raise ValueError(f"Invalid frequency: {freq!r}")
    f = freq.strip().upper()

    if f == "MONTH-END":
        def rule(y, m):
            return datetime.date(y, m, calendar.monthrange(y, m)[1])
        return rule

    if f == "QUARTER-END":
        def rule(y, m):
            if m % 3 != 0:
                return None
            return datetime.date(y, m, calendar.monthrange(y, m)[1])
        return rule

    match = re.fullmatch(r"([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)", f)
    if match:
        week = int(match.group(1))
        weekday = _WEEKDAYS[match.group(2)]

        def rule(y, m):
            first_wd = datetime.date(y, m, 1).weekday()
            day = 1 + (weekday - first_wd) % 7 + 7 * (week - 1)
            return datetime.date(y, m, day)  # day <= 28, always valid
        return rule

    raise ValueError(f"Invalid frequency: {freq!r}")


def forecast_schedule(start_date, freq, sales):
    start = _parse_start(start_date)
    rule = _make_rule(freq)
    sales = list(sales)

    result = []
    year, month = start.year, start.month
    while len(result) < len(sales):
        d = rule(year, month)
        if d is not None and d >= start:
            result.append((d.isoformat(), sales[len(result)]))
        month += 1
        if month > 12:
            month = 1
            year += 1
    return result
```

Example:

```python
>>> forecast_schedule('2021-01-01', '2-FRI', [272, 147, 217])
[('2021-01-08', 272), ('2021-02-12', 147), ('2021-03-12', 217)]
>>> forecast_schedule('2021-01-31', 'month-end', [1, 2, 3])
[('2021-01-31', 1), ('2021-02-28', 2), ('2021-03-31', 3)]
>>> forecast_schedule('2021-04-01', 'quarter-end', [10, 20])
[('2021-06-30', 10), ('2021-09-30', 20)]
```

Notes:
- The start date must be exactly `YYYY-MM-DD` and a real calendar date (e.g. `'2021-02-30'` raises `ValueError`).
- An unrecognized `freq` also raises `ValueError`.
- An empty `sales` list returns `[]`.

