import csv
import io
from collections import Counter


def _parse_number(value):
    """Convert a Sales cell to int if possible, otherwise to float."""
    text = value.strip()
    try:
        return int(text)
    except ValueError:
        try:
            return float(text)
        except ValueError:
            raise ValueError(f"Invalid Sales value: {value!r}")


def sales_report(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    reader = csv.DictReader(io.StringIO(csv_text))

    # Normalise header names (strip surrounding whitespace)
    if reader.fieldnames is None:
        raise ValueError("CSV text has no header row")
    reader.fieldnames = [name.strip() for name in reader.fieldnames]

    required = {"Customer", "Category", "Sales"}
    missing = required - set(reader.fieldnames)
    if missing:
        raise ValueError(f"Missing required column(s): {', '.join(sorted(missing))}")

    seen_customers = set()
    total_sales = 0
    category_counts = Counter()

    for row in reader:
        customer = (row.get("Customer") or "").strip()
        # Skip completely blank lines
        if not any((v or "").strip() for v in row.values() if isinstance(v, str)):
            continue
        if customer in seen_customers:
            continue
        seen_customers.add(customer)

        total_sales += _parse_number(row.get("Sales") or "")
        category_counts[(row.get("Category") or "").strip()] += 1

    if category_counts:
        # Highest count first; ties broken by alphabetical order
        most_popular = min(category_counts.items(), key=lambda kv: (-kv[1], kv[0]))[0]
    else:
        most_popular = None

    return {"Total Sales": total_sales, "Most Popular Category": most_popular}
