import json
import math

import pandas as pd


def numeric_correlation_from_json(json_text):
    """
    Parse a JSON object mapping column names to equal-length lists of values
    and return the pairwise Pearson correlation matrix of its numeric columns.

    Returns a dict of dicts: {col_i: {col_j: corr(col_i, col_j), ...}, ...}

    Raises ValueError if the text is not valid JSON, is not a JSON object of
    columns, or holds no data.
    """
    # Parse JSON.
    try:
        data = json.loads(json_text)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError(f"Invalid JSON input: {exc}") from exc

    # Validate structure.
    if not isinstance(data, dict):
        raise ValueError("JSON must be an object mapping column names to lists of values")
    if not data:
        raise ValueError("Input data is empty")

    for name, values in data.items():
        if not isinstance(values, list):
            raise ValueError(f"Column {name!r} must be a list of values")

    # Build the DataFrame. pandas raises ValueError for unequal lengths.
    try:
        df = pd.DataFrame(data)
    except ValueError as exc:
        raise ValueError(f"Could not build table from JSON data: {exc}") from exc

    if df.empty:
        raise ValueError("Input data is empty")

    # Keep only numeric columns (booleans are excluded).
    numeric_df = df.select_dtypes(include="number").select_dtypes(exclude="bool")
    if numeric_df.shape[1] == 0:
        return {}

    corr = numeric_df.corr(method="pearson")

    # Convert to plain Python floats in a nested dict.
    result = {}
    for col in corr.columns:
        result[col] = {}
        for row in corr.index:
            value = corr.at[row, col]
            result[col][row] = float(value) if not pd.isna(value) else math.nan
    return result
```

Example:

```python
>>> numeric_correlation_from_json('{"a": [1, 2, 3], "b": [2, 4, 7]}')
{'a': {'a': 1.0, 'b': 0.993399267798783}, 'b': {'a': 0.993399267798783, 'b': 1.0}}

>>> numeric_correlation_from_json('{"a": [1, 2, 3], "b": [2, 4, 7], "c": ["x", "y", "z"]}')
{'a': {'a': 1.0, 'b': 0.993399267798783}, 'b': {'a': 0.993399267798783, 'b': 1.0}}

>>> numeric_correlation_from_json('not json')
