```

Notes:
- Non-numeric columns such as strings or mixed types are ignored. Boolean columns are also treated as non-numeric.
- Missing values (`null`) in otherwise numeric columns become NaN. They are handled pairwise, as pandas does.
- A constant column has an undefined correlation, so it yields `nan`.
- If no numeric columns remain, an empty dict is returned.

```python
import json
import math


def _is_number(value):
    """Return True for real numbers (int/float). Booleans are excluded."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _is_missing(value):
    """Return True for null (None) or NaN values."""
    return value is None or (isinstance(value, float) and math.isnan(value))


def _pearson(xs, ys):
    """Pearson correlation using pairwise-complete observations.

    Returns NaN if there are fewer than two usable pairs
    or either series has zero variance.
    """
    pairs = [(x, y) for x, y in zip(xs, ys)
             if not _is_missing(x) and not _is_missing(y)]
    n = len(pairs)
    if n < 2:
        return float("nan")

    mean_x = sum(p[0] for p in pairs) / n
    mean_y = sum(p[1] for p in pairs) / n

    sxy = sxx = syy = 0.0
    for x, y in pairs:
        dx = x - mean_x
        dy = y - mean_y
        sxy += dx * dy
        sxx += dx * dx
        syy += dy * dy

    divisor = math.sqrt(sxx * syy)
    if divisor == 0:
        return float("nan")

    r = sxy / divisor
    # Guard against tiny floating-point overshoot.
    return max(-1.0, min(1.0, r))


def numeric_correlation_from_json(json_text):
    """Parse a JSON object of column -> list of values and return the
    pairwise Pearson correlation matrix of its numeric columns.

    Raises ValueError if the text is not valid JSON or the data is empty.
    """
    try:
        data = json.loads(json_text)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON must be an object mapping column names to lists")
    if not data:
        raise ValueError("Data is empty")

    lengths = set()
    for name, values in data.items():
        if not isinstance(values, list):
            raise ValueError(f"Column {name!r} is not a list")
        lengths.add(len(values))

    if len(lengths) != 1:
        raise ValueError("All columns must have the same length")
    if lengths.pop() == 0:
        raise ValueError("Data is empty")

    # A column is numeric if every non-missing value is a number
    # and it contains at least one actual number.
    numeric_cols = []
    for name, values in data.items():
        present = [v for v in values if not _is_missing(v)]
        if present and all(_is_number(v) for v in present):
            numeric_cols.append(name)

    result = {name: {} for name in numeric_cols}
    for i, a in enumerate(numeric_cols):
        for b in numeric_cols[i:]:
            if a == b:
                r = _pearson(data[a], data[a])
                r = 1.0 if not math.isnan(r) else r
            else:
                r = _pearson(data[a], data[b])
            result[a][b] = r
            result[b][a] = r

    # Keep inner dicts in column order.
    return {a: {b: result[a][b] for b in numeric_cols} for a in numeric_cols}
```

Example:

```python
>>> numeric_correlation_from_json('{"a": [1, 2, 3], "b": [2, 4, 7]}')
{'a': {'a': 1.0, 'b': 0.993399267798783}, 'b': {'a': 0.993399267798783, 'b': 1.0}}

>>> numeric_correlation_from_json('{"a": [1, 2, 3], "name": ["x", "y", "z"], "b": [3, 2, 1]}')
{'a': {'a': 1.0, 'b': -1.0}, 'b': {'a': -1.0, 'b': 1.0}}
```

**What the function does:**
- **Errors:** It raises `ValueError` for:
  - malformed JSON
  - a top-level value that isn't an object
  - no columns or zero rows
  - mismatched column lengths
- **Numeric columns:** A column counts as numeric if every non-null value is an `int` or `float`. Booleans are excluded. Text, mixed, or all-null columns are ignored.
- **Missing values:** `null` (or NaN) values are skipped per pair of columns, so only rows where both columns have a value are used.
- **Undefined correlations:** If a column has zero variance (e.g. a constant column), or a pair has fewer than two usable rows, the correlation is `nan`.

