import csv
import io
import math


def _cube_root(x):
    """Real cube root of x. Negative inputs give negative results."""
    if x == 0 or not math.isfinite(x):
        return x  # handles 0.0, -0.0, inf, -inf and nan

    if hasattr(math, "cbrt"):          # Python 3.11+
        return math.cbrt(x)

    a = abs(x)
    r = a ** (1.0 / 3.0)
    # One Newton step to remove floating-point error (e.g. 64 ** (1/3) = 3.9999999999999996)
    r = r - (r * r * r - a) / (3.0 * r * r)
    # Snap to an exact integer root when one exists
    n = round(r)
    if n ** 3 == a:
        r = float(n)
    return math.copysign(r, x)


def csv_cube_roots(csv_text, columns):
    reader = csv.reader(io.StringIO(csv_text))

    # Find the header, skipping any leading blank lines
    header = None
    for row in reader:
        if row:
            header = [name.strip() for name in row]
            break
    if header is None:
        header = []

    if len(set(header)) != len(header):
        raise ValueError("Duplicate column names in header")

    data = {name: [] for name in header}

    for line_no, row in enumerate(reader, start=2):
        if not row:                    # skip blank lines
            continue
        if len(row) != len(header):
            raise ValueError(
                f"Row {line_no} has {len(row)} fields, expected {len(header)}"
            )
        for name, cell in zip(header, row):
            try:
                value = float(cell)
            except ValueError:
                raise ValueError(
                    f"Non-numeric value {cell!r} in column {name!r} (row {line_no})"
                ) from None
            data[name].append(value)

    roots = {}
    for col in columns:
        if col not in data:
            raise KeyError(col)
        roots[col] = [_cube_root(v) for v in data[col]]

    return data, roots
```

