```python
import math
from numbers import Real


def _is_numeric_column(values):
    return all(isinstance(v, Real) and not isinstance(v, bool) for v in values)


def standardize_and_correlate(table):
    if not isinstance(table, dict) or not table:
        raise ValueError("table is empty")

    lengths = {len(col) for col in table.values()}
    if len(lengths) != 1:
        raise ValueError("all columns must have the same length")
    n = lengths.pop()
    if n == 0:
        raise ValueError("table is empty")

    numeric_names = [name for name, col in table.items() if _is_numeric_column(col)]
    if not numeric_names:
        raise ValueError("table has no numeric columns")

    # Deviations from the mean and sum of squared deviations for each numeric column
    deviations = {}
    sum_sq = {}
    for name in numeric_names:
        col = [float(v) for v in table[name]]
        mean = math.fsum(col) / n
        dev = [v - mean for v in col]
        deviations[name] = dev
        sum_sq[name] = math.fsum(d * d for d in dev)

    # Standardized table: same column order, non-numeric columns unchanged
    standardized = {}
    for name, col in table.items():
        if name in deviations:
            std = math.sqrt(sum_sq[name] / n)  # population standard deviation
            if std == 0:
                standardized[name] = [0.0] * n
            else:
                standardized[name] = [d / std for d in deviations[name]]
        else:
            standardized[name] = list(col)

    # Pearson correlation matrix of the numeric columns, in table order
    k = len(numeric_names)
    corr = [[0.0] * k for _ in range(k)]
    for i in range(k):
        a = numeric_names[i]
        for j in range(i, k):
            b = numeric_names[j]
            if sum_sq[a] == 0 or sum_sq[b] == 0:
                r = float("nan")
            elif i == j:
                r = 1.0
            else:
                sxy = math.fsum(x * y for x, y in zip(deviations[a], deviations[b]))
                r = sxy / math.sqrt(sum_sq[a] * sum_sq[b])
                r = max(-1.0, min(1.0, r))
            corr[i][j] = corr[j][i] = r

    return standardized, corr
```

## Example

```python
>>> standardize_and_correlate({'x': [1, 2, 3], 'n': ['a', 'b', 'c'], 'y': [3, 1, 2]})
({'x': [-1.224744871391589, 0.0, 1.224744871391589],
  'n': ['a', 'b', 'c'],
  'y': [1.224744871391589, -1.224744871391589, 0.0]},
 [[1.0, -0.5], [-0.5, 1.0]])
```

For `x`, the deviations are `[-1, 0, 1]`, giving a population standard deviation of `√(2/3)`. For `y`, the deviations are `[1, -1, 0]`. The cross-sum is `-1`, so the correlation is `-1 / √(2·2) = -0.5` exactly.

```python
from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    """Collects the text of <td> cells for every <tr> row, in document order.

    Copes with nested tables, omitted end tags (</td>, </tr>), implicit rows
    (cells appearing without an enclosing <tr>), and entity decoding.
    """

    def __init__(self):
        super().__init__(convert_charrefs=True)  # decodes entities in text
        self.rows = []
        # One context per (nested) table; the base context covers markup
        # that is not inside any <table>.
        self.contexts = [self._new_context()]
        self._skip_depth = 0  # inside <script>/<style>

    @staticmethod
    def _new_context():
        # 'row'  -> index into self.rows of the currently open row (or None)
        # 'cell' -> dict(kind='td'|'th', buf=[...]) for the open cell (or None)
        return {"row": None, "cell": None}

    # ---- helpers -------------------------------------------------------
    def _close_cell(self, ctx):
        cell = ctx["cell"]
        if cell is not None:
            if cell["kind"] == "td" and ctx["row"] is not None:
                self.rows[ctx["row"]].append("".join(cell["buf"]).strip())
            ctx["cell"] = None

    def _close_row(self, ctx):
        self._close_cell(ctx)
        ctx["row"] = None

    def _open_row(self, ctx):
        ctx["row"] = len(self.rows)
        self.rows.append([])

    # ---- parser callbacks ---------------------------------------------
    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self._skip_depth += 1
            return
        ctx = self.contexts[-1]
        if tag == "table":
            self.contexts.append(self._new_context())
        elif tag == "tr":
            self._close_row(ctx)
            self._open_row(ctx)
        elif tag in ("td", "th"):
            self._close_cell(ctx)
            if ctx["row"] is None:          # cell without <tr>: implicit row
                self._open_row(ctx)
            ctx["cell"] = {"kind": tag, "buf": []}
        elif tag in ("thead", "tbody", "tfoot"):
            self._close_row(ctx)

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            if self._skip_depth:
                self._skip_depth -= 1
            return
        ctx = self.contexts[-1]
        if tag in ("td", "th"):
            self._close_cell(ctx)
        elif tag in ("tr", "thead", "tbody", "tfoot"):
            self._close_row(ctx)
        elif tag == "table":
            if len(self.contexts) > 1:
                self._close_row(ctx)
                self.contexts.pop()

    def handle_data(self, data):
        if self._skip_depth:
            return
        # Text belongs to every open <td> (an outer cell's text content
        # includes the text of anything nested inside it).
        for ctx in self.contexts:
            cell = ctx["cell"]
            if cell is not None and cell["kind"] == "td":
                cell["buf"].append(data)

    def close(self):
        super().close()
        # Finalise anything left open (unclosed tags at end of input).
        for ctx in reversed(self.contexts):
            self._close_row(ctx)


def extract_table_rows(html):
    """Return a list of rows; each row is a list of its <td> cell texts."""
    parser = _TableRowParser()
    parser.feed(html or "")
    parser.close()
    return parser.rows
```

