- Contents of `<script>`/`<style>` are ignored.

```python
from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    """Collects <td> text for every <tr>, in document order.

    Handles nested tables, omitted end tags (</td>, </tr>) and stray tags.
    """

    def __init__(self):
        super().__init__(convert_charrefs=True)  # decodes entities in handle_data
        self.rows = []    # final result: one list of cell texts per row
        self.stack = []   # open structural elements: dicts with a 'kind' key
        self._skip = 0    # depth inside <script>/<style>

    # ---- helpers -------------------------------------------------------
    def _close_top(self):
        item = self.stack.pop()
        if item["kind"] == "cell" and item["is_td"]:
            self.rows[item["row"]].append("".join(item["buf"]).strip())

    def _top_kind(self):
        return self.stack[-1]["kind"] if self.stack else None

    def _find_above_table(self, kind):
        """Index of the nearest `kind` element not hidden behind a table."""
        for i in range(len(self.stack) - 1, -1, -1):
            k = self.stack[i]["kind"]
            if k == kind:
                return i
            if k == "table":
                return None
        return None

    def _pop_through(self, index):
        while len(self.stack) > index:
            self._close_top()

    def _open_row(self):
        # An open row/cell at this level is implicitly closed by a new row.
        while self._top_kind() in ("cell", "tr"):
            self._close_top()
        self.rows.append([])
        self.stack.append({"kind": "tr", "row": len(self.rows) - 1})

    # ---- parser callbacks ---------------------------------------------
    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self._skip += 1
            return
        if tag == "table":
            self.stack.append({"kind": "table"})
        elif tag == "tr":
            self._open_row()
        elif tag in ("td", "th"):
            # A new cell implicitly closes the previous cell in this row.
            while self._top_kind() == "cell":
                self._close_top()
            if self._top_kind() != "tr":
                self._open_row()  # cell without an enclosing <tr>
            self.stack.append({
                "kind": "cell",
                "is_td": tag == "td",
                "row": self.stack[-1]["row"],
                "buf": [],
            })

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            if self._skip:
                self._skip -= 1
            return
        if tag in ("td", "th"):
            i = self._find_above_table("cell")
            if i is not None:
                self._pop_through(i)
        elif tag == "tr":
            i = self._find_above_table("tr")
            if i is not None:
                self._pop_through(i)
        elif tag == "table":
            for i in range(len(self.stack) - 1, -1, -1):
                if self.stack[i]["kind"] == "table":
                    self._pop_through(i)
                    break

    def handle_data(self, data):
        if self._skip:
            return
        # Text belongs to every open <td> (a nested table's text is part
        # of the outer cell's text content too).
        for item in self.stack:
            if item["kind"] == "cell" and item["is_td"]:
                item["buf"].append(data)

    def close(self):
        super().close()
        while self.stack:  # flush anything left unclosed
            self._close_top()


def extract_table_rows(html):
    parser = _TableRowParser()
    parser.feed(html)
    parser.close()
    return parser.rows
```

