How it works:

- **Parsing:** It uses Python's built-in `html.parser`. With `convert_charrefs=True`, entities like `&amp;` are decoded before the text reaches `handle_data`.
- **Tag removal:** Tags inside a cell are dropped, and only their text is collected. The joined text is stripped when the cell closes.
- **Header cells:** `<th>` cells are tracked so they close correctly, but their text is never added to the row. A header-only row therefore becomes `[]`.
- **Omitted end tags:** HTML lets you leave out `</td>`, `</tr>` or `</table>`. A new `<td>` or `<th>` closes the previous cell, a new `<tr>` closes the previous row, and anything still open at the end is flushed.
- **Nested tables:** Each inner row is listed separately, in document order. The outer cell's text includes the inner table's text, because tags are removed from the cell's contents.
- **Script and style:** Text inside `<script>` and `<style>` is ignored.

```python
from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)  # decode entities in text
        self.rows = []         # result: one list of cell texts per <tr>
        self.depth = 0         # current <table> nesting depth
        self.open_rows = []    # stack of (table_depth, row_index)
        self.open_cells = []   # stack of open <td>/<th> cells

    # ---- helpers -------------------------------------------------------
    def _close_cell(self, cell):
        if cell["slot"] is not None:
            text = "".join(cell["parts"]).strip()
            self.rows[cell["row"]][cell["slot"]] = text

    def _close_cells_at(self, depth):
        while self.open_cells and self.open_cells[-1]["depth"] >= depth:
            self._close_cell(self.open_cells.pop())

    def _close_rows_at(self, depth):
        self._close_cells_at(depth)
        while self.open_rows and self.open_rows[-1][0] >= depth:
            self.open_rows.pop()

    # ---- parser callbacks ---------------------------------------------
    def handle_starttag(self, tag, attrs):
        if tag == "table":
            self.depth += 1
        elif tag == "tr":
            # A new <tr> implicitly closes an unclosed row in the same table.
            self._close_rows_at(self.depth)
            self.rows.append([])
            self.open_rows.append((self.depth, len(self.rows) - 1))
        elif tag in ("td", "th"):
            # A new cell implicitly closes an unclosed cell in the same table.
            self._close_cells_at(self.depth)
            row = None
            if self.open_rows and self.open_rows[-1][0] == self.depth:
                row = self.open_rows[-1][1]
            slot = None
            if tag == "td" and row is not None:
                slot = len(self.rows[row])
                self.rows[row].append("")  # reserve position, fill on close
            self.open_cells.append(
                {"depth": self.depth, "row": row, "slot": slot, "parts": []}
            )

    def handle_endtag(self, tag):
        if tag in ("td", "th"):
            if self.open_cells and self.open_cells[-1]["depth"] == self.depth:
                self._close_cell(self.open_cells.pop())
        elif tag == "tr":
            if self.open_rows and self.open_rows[-1][0] == self.depth:
                self._close_rows_at(self.depth)
        elif tag == "table":
            if self.depth > 0:
                self._close_rows_at(self.depth)
                self.depth -= 1

    def handle_data(self, data):
        # Text belongs to every open cell (outer cells include nested text).
        for cell in self.open_cells:
            cell["parts"].append(data)

    def finish(self):
        self.close()
        while self.open_cells:
            self._close_cell(self.open_cells.pop())
        self.open_rows.clear()
        return self.rows


def extract_table_rows(html):
    """Return the text of the <td> cells of every <tr> row, in document order."""
    parser = _TableRowParser()
    parser.feed(html)
    return parser.finish()
```

