- `<th>` cells are parsed but not recorded. A row with only header cells therefore yields `[]`.
- HTML that omits closing tags is handled. A new `<tr>` closes an open row in the same table, and a new `<td>` or `<th>` closes an open cell. Unclosed cells are closed at the end of input.
- Nested tables are supported. Rows of an inner table appear in document order as separate entries. The outer cell's text includes the inner table's text, as with `textContent`.

```python
from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    def __init__(self):
        # convert_charrefs=True makes the parser decode entities such as &amp; in text.
        super().__init__(convert_charrefs=True)
        self.rows = []    # one list of cell buffers per <tr>, in document order
        self.stack = []   # open elements: (tag, payload)

    def _pop(self):
        # Removing a <td> entry is all it takes to close it, since its text
        # buffer is already stored in its row.
        self.stack.pop()

    def _pop_until(self, tag, boundary=("table",)):
        """Close elements up to and including `tag`, but only if `tag` is open
        before reaching a boundary element (e.g. an enclosing table)."""
        for i in range(len(self.stack) - 1, -1, -1):
            t = self.stack[i][0]
            if t == tag:
                while len(self.stack) > i:
                    self._pop()
                return
            if t in boundary:
                return

    def handle_starttag(self, tag, attrs):
        if tag == "table":
            self.stack.append(("table", None))
        elif tag == "tr":
            # A new row implicitly closes any open cell/row in the same table.
            while self.stack and self.stack[-1][0] in ("td", "th", "tr"):
                self._pop()
            row = []
            self.rows.append(row)
            self.stack.append(("tr", row))
        elif tag in ("td", "th"):
            # A new cell implicitly closes any open cell in the same row.
            while self.stack and self.stack[-1][0] in ("td", "th"):
                self._pop()
            # Find the row this cell belongs to (not crossing a table boundary).
            row = None
            for t, payload in reversed(self.stack):
                if t == "tr":
                    row = payload
                    break
                if t == "table":
                    break
            if tag == "td" and row is not None:
                buf = []
                row.append(buf)
                self.stack.append(("td", buf))
            else:
                self.stack.append((tag, None))

    def handle_endtag(self, tag):
        if tag in ("td", "th"):
            self._pop_until(tag, boundary=("table", "tr"))
        elif tag == "tr":
            self._pop_until("tr")
        elif tag == "table":
            self._pop_until("table", boundary=())

    def handle_data(self, data):
        # Text belongs to every open <td> (a cell's text includes its descendants).
        for t, payload in self.stack:
            if t == "td" and payload is not None:
                payload.append(data)


def extract_table_rows(html):
    parser = _TableRowParser()
    parser.feed(html)
    parser.close()
    return [["".join(buf).strip() for buf in row] for row in parser.rows]
```

