How it works:

- **Parsing:** It uses Python's built-in `HTMLParser`. Setting `convert_charrefs=True` decodes entities such as `&amp;` and `&#233;`. Tags are dropped, and only text is collected.
- **Row order:** A row's entry is added when its `<tr>` start tag is seen. This keeps rows in document order, including rows of nested tables.
- **Header cells:** `<th>` cells are tracked so they close properly, but their text is never recorded. A row with only header cells therefore gives `[]`.
- **Omitted closing tags:** `</td>` and `</tr>` are optional in HTML. A new `<td>` or `<th>` closes any open cell, and a new `<tr>` closes the open row, but only within the same table.
- **Nested tables:** The inner table's rows appear as their own entries. The outer cell's text includes the inner table's text, since it contains it.
- **Edge cases:** Cells outside any `<tr>` are ignored, and the result is `[]` if there are no rows.

The function below uses Python's built-in `html.parser` and also handles nested tables and omitted closing tags.

```python
from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    """Collects the <td> texts of every <tr> in document order."""

    _CELL_TAGS = ("td", "th")
    _SECTION_TAGS = ("thead", "tbody", "tfoot")

    def __init__(self):
        # convert_charrefs=True decodes entities such as &amp; and &#39;
        super().__init__(convert_charrefs=True)
        self.rows = []
        # One frame per open <table>. The base frame catches rows that
        # appear outside any <table> element.
        self.frames = [self._new_frame()]

    @staticmethod
    def _new_frame():
        # row: index into self.rows of the open row, or None
        # cell: dict describing the open cell, or None
        return {"row": None, "cell": None}

    # ----- helpers --------------------------------------------------------
    def _close_cell(self, frame):
        cell = frame["cell"]
        if cell is None:
            return
        if cell["tag"] == "td":
            text = "".join(cell["parts"]).strip()
            self.rows[cell["row"]].append(text)
        frame["cell"] = None

    def _close_row(self, frame):
        self._close_cell(frame)
        frame["row"] = None

    def _open_row(self, frame):
        self._close_row(frame)
        self.rows.append([])
        frame["row"] = len(self.rows) - 1

    # ----- parser callbacks ----------------------------------------------
    def handle_starttag(self, tag, attrs):
        frame = self.frames[-1]
        if tag == "table":
            self.frames.append(self._new_frame())
        elif tag == "tr":
            self._open_row(frame)
        elif tag in self._CELL_TAGS:
            # An open cell is closed implicitly by a new one.
            self._close_cell(frame)
            if frame["row"] is None:
                # A cell with no enclosing <tr> gets an implicit row.
                self._open_row(frame)
            frame["cell"] = {"tag": tag, "row": frame["row"], "parts": []}
        elif tag in self._SECTION_TAGS:
            self._close_row(frame)

    def handle_endtag(self, tag):
        frame = self.frames[-1]
        if tag == "table":
            self._close_row(frame)
            if len(self.frames) > 1:
                self.frames.pop()
        elif tag == "tr":
            self._close_row(frame)
        elif tag in self._CELL_TAGS:
            self._close_cell(frame)
        elif tag in self._SECTION_TAGS:
            self._close_row(frame)

    def handle_data(self, data):
        # Text belongs to every open cell, so a cell that contains a
        # nested table gets the nested text too.
        for frame in self.frames:
            if frame["cell"] is not None:
                frame["cell"]["parts"].append(data)

    def finish(self):
        self.close()
        # Close any elements left open, innermost first.
        for frame in reversed(self.frames):
            self._close_row(frame)
        return self.rows


def extract_table_rows(html):
    """
    Return the <td> texts of every <tr> in `html`, in document order.

    Each row is a list of its <td> cell texts with tags removed,
    entities decoded and surrounding whitespace stripped. <th> cells
    are ignored, so a header-only row gives []. If there are no rows,
    the result is [].
    """
    parser = _TableRowParser()
    parser.feed(html)
    return parser.finish()
```

